To solve this problem, we need to implement a sorting algorithm with a time complexity of O(n log n) or better, such as QuickSort or MergeSort. We'll also need to handle edge cases and ensure that the input is valid. Here's a Python implementation that meets these requirements:

```python
def quickselect(arr, left, right, k):
    """Helper function to perform the QuickSelect algorithm."""
    if left == right:
        return arr[left]

    pivot_index = partition(arr, left, right)

    if k == pivot_index:
        return arr[k]
    elif k < pivot_index:
        return quickselect(arr, left, pivot_index - 1, k)
    else:
        return quickselect(arr, pivot_index + 1, right, k)

def partition(arr, left, right):
    """Helper function to partition the array around a pivot."""
    pivot = arr[right]
    i = left
    for j in range(left, right):
        if arr[j] <= pivot:
            arr[i], arr[j] = arr[j], arr[i]
            i += 1
    arr[i], arr[right] = arr[right], arr[i]
    return i

def calculate_median(arr):
    """Calculate the median of an array without using built-in functions."""
    if not isinstance(arr, list):
        raise TypeError("Input must be a list.")

    if not all(isinstance(x, (int, float)) for x in arr):
        raise ValueError("All elements in the array must be numeric.")

    n = 0
    for _ in arr:
        n += 1

    if n == 0:
        raise ValueError("Array is empty.")

    if n == 1:
        return arr[0]

    # Use QuickSelect to find the median
    if n % 2 == 1:
        # Odd number of elements
        median = quickselect(arr, 0, n - 1, n // 2)
    else:
        # Even number of elements
        left_mid = quickselect(arr, 0, n - 1, n // 2 - 1)
        right_mid = quickselect(arr, 0, n - 1, n // 2)
        median = (left_mid + right_mid) / 2.0

    return median

# Example usage:
try:
    array = [3, 1, 2, 5, 4]
    print("Median:", calculate_median(array))
except Exception as e:
    print("Error:", e)
