Here is an implementation of a doubly linked list node with the mentioned methods:

```python
class DoublyLinkedListNode:
    def __init__(self, data):
        self.data = data
        self.next = None
        self.prev = None

    def insert_after(self, new_node):
        new_node.next = self.next
        if self.next:
            self.next.prev = new_node
        self.next = new_node
        new_node.prev = self

    def delete(self):
        if self.prev:
            self.prev.next = self.next
        if self.next:
            self.next.prev = self.prev

    def find_previous(self, data):
        current = self
        while current.prev:
            current = current.prev
            if current.data == data:
                return current
        return None

    def find_next(self, data):
        current = self
        while current.next:
            current = current.next
            if current.data == data:
                return current
        return None

    def find_last(self):
        current = self
        while current.next:
            current = current.next
        return current

    def reverse(self):
        current = self
        while current.next:
            current = current.next
        while current:
            current.next, current.prev = current.prev, current.next
            current = current.next

    def sort(self):
        current = self
        while current.next:
            current = current.next
        while current:
            if current.prev and current.data < current.prev.data:
                current.data, current.prev.data = current.prev.data, current.data
                current = current.prev
            else:
                current = current.next

    def merge(self, other_list):
        current = self
        while current.next:
            current = current.next
        current.next = other_list
        other_list.prev = current
        self.sort()

    def remove_duplicates(self):
        current = self
        while current:
            data = current.data
            runner = current.next
            while runner:
                if runner.data == data:
                    runner.delete()
                runner = runner.next
            current = current.next

    def find_kth_from_end(self, k):
        slow = self
        fast = self
        for _ in range(k):
            if fast.next:
                fast = fast.next
            else:
                return None
        while fast.next:
            fast = fast.next
            slow = slow.next
        return slow

