def is_palindrome(n):
    """Check if a number is a palindrome."""
    return str(n) == str(n)[::-1]

def is_prime(n):
    """Check if a number is a prime."""
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def is_perfect_cube(n):
    """Check if a number is a perfect cube."""
    cube_root = round(n ** (1/3))
    return cube_root ** 3 == n

def display_primes(a, b):
    """Display palindromic primes in the range [a, b] that are not perfect cubes."""
    for num in range(a, b + 1):
        if is_prime(num) and is_palindrome(num) and not is_perfect_cube(num):
            print(num)

def get_valid_input(prompt):
    """Get valid integer input from the user."""
    while True:
        try:
            value = int(input(prompt))
            return value
        except ValueError:
            print("Invalid input. Please enter an integer.")

def main():
    """Main function to execute the program."""
    print("Enter the range to find palindromic primes that are not perfect cubes.")
    a = get_valid_input("Enter the start of the range: ")
    b = get_valid_input("Enter the end of the range: ")

    if a > b:
        print("Invalid range. The start of the range must be less than or equal to the end.")
    else:
        print(f"Palindromic primes (not perfect cubes) between {a} and {b}:")
        display_primes(a, b)

if __name__ == "__main__":
    main()
```

