```python
def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_primes(start, count=50):
    """Generate an array of the first 'count' prime numbers greater than 'start'."""
    if start < 101:
        raise ValueError("Starting number must be greater than or equal to 101.")

    primes = []
    num = start
    while len(primes) < count:
        if is_prime(num):
            primes.append(num)
        num += 1

    return primes

# Generate the first 50 prime numbers greater than 100
