import random

class Person:
    def __init__(self, name, age, gender, hobbies=None):
        self.name = self.validate_name(name)
        self.age = self.validate_age(age)
        self.gender = self.validate_gender(gender)
        self.hobbies = self.validate_hobbies(hobbies if hobbies else [])

    def validate_name(self, name):
        if not name or not isinstance(name, str) or len(name) > 100:
            raise ValueError("Name must be a non-empty string with a maximum length of 100 characters.")
        return name

    def validate_age(self, age):
        if not isinstance(age, int) or not (0 <= age <= 150):
            raise ValueError("Age must be a positive integer between 0 and 150.")
        return age

    def validate_gender(self, gender):
        if gender not in ["male", "female"]:
            raise ValueError("Gender must be either 'male' or 'female'.")
        return gender

    def validate_hobbies(self, hobbies):
        validated_hobbies = []
        for hobby in hobbies:
            if not hobby or not isinstance(hobby, str) or len(hobby) > 100:
                raise ValueError("Each hobby must be a non-empty string with a maximum length of 100 characters.")
            validated_hobbies.append(hobby)
        return validated_hobbies

    def addHobby(self, hobby):
        if not hobby or not isinstance(hobby, str) or len(hobby) > 100:
            raise ValueError("Hobby must be a non-empty string with a maximum length of 100 characters.")
        if hobby not in self.hobbies:
            self.hobbies.append(hobby)

    def removeHobby(self, hobby):
        if hobby in self.hobbies:
            self.hobbies.remove(hobby)

    def changeName(self, new_name):
        self.name = self.validate_name(new_name)

    def changeAge(self, new_age):
        self.age = self.validate_age(new_age)

    def countHobbies(self):
        return len(self.hobbies)

    def printHobbies(self):
        if not self.hobbies:
            print("No hobbies.")
        else:
            for hobby in self.hobbies:
                print(hobby)

    def getHobbies(self):
        return self.hobbies.copy()

    def hasHobby(self, hobby):
        return hobby in self.hobbies

    def getRandomHobby(self):
        if not self.hobbies:
            raise ValueError("No hobbies available to select from.")
        return random.choice(self.hobbies)

    def clearHobbies(self):
        self.hobbies.clear()

# Example usage:
