    person.printHobbies()
    person.changeName("Alicia")
    person.changeAge(31)
    print("Name:", person.name, "Age:", person.age)
    print("Number of hobbies:", person.countHobbies())
    person.clearHobbies()
    person.printHobbies()
except ValueError as e:
    print(e)
