def is_prime(num):
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def sum_of_proper_divisors_excluding_primes(n):
    if not isinstance(n, int) or n <= 0:
        raise ValueError("Input must be a positive integer.")

    if n == 1:
        return 0

    sum_divisors = 0

    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            if i != n and not is_prime(i):
                sum_divisors += i
            if i != 1 and i != n // i and n // i != n and not is_prime(n // i):
                sum_divisors += n // i

    return sum_divisors

