```javascript
function checkNumber(input) {
    let number;

    // Try to parse the input as an integer
    try {
        number = parseInt(input, 10);

        // Check if the parsed number is an integer
        if (isNaN(number) || !Number.isInteger(number)) {
            throw new Error("Input is not a valid integer.");
        }

        // Check if the number is within the specified range
        if (number < 1 || number > 100) {
            console.log("The number is outside the valid range (1-100). Please enter a number between 1 and 100.");
            return;
        }

        // Check if the number is prime
        if (isPrime(number)) {
            console.log(`${number} is a prime number.`);
        } else {
            console.log(`${number} is not a prime number.`);
        }

    } catch (error) {
        console.log("Error: " + error.message);
    }
}

function isPrime(num) {
    if (num <= 1) return false;
    if (num <= 3) return true;

    // Check from 2 to sqrt(num)
    for (let i = 2; i <= Math.sqrt(num); i++) {
        if (num % i === 0) return false;
    }

    return true;
}

// Example usage
let number = 10;
checkNumber(number);

// Test with different inputs
checkNumber("abc"); // Non-integer input
checkNumber(101);   // Out of range
checkNumber(7);     // Prime number
checkNumber(10);    // Non-prime number
```

