To design a data structure for the inventory of an online grocery store that meets the specified requirements, we can use a combination of a dictionary and classes in Python. The dictionary will allow us to achieve O(1) average time complexity for adding, removing, and updating items, while classes will help encapsulate the item details and operations.

Here's a detailed implementation:

```python
class NutritionalInfo:
    def __init__(self, calories, carbohydrates, vitamins):
        self.calories = calories  # Integer
        self.carbohydrates = carbohydrates  # Float
        self.vitamins = vitamins  # Dictionary of vitamins

    def __repr__(self):
        return f"NutritionalInfo(calories={self.calories}, carbohydrates={self.carbohydrates}, vitamins={self.vitamins})"

class GroceryItem:
    def __init__(self, name, quantity, price, nutritional_info):
        self.name = name
        self.quantity = quantity
        self.price = price
        self.nutritional_info = nutritional_info

    def __repr__(self):
        return (f"GroceryItem(name={self.name}, quantity={self.quantity}, "
                f"price={self.price}, nutritional_info={self.nutritional_info})")

class Inventory:
    def __init__(self):
        self.items = {}

    def add_item(self, name, quantity, price, nutritional_info):
        if not (1 <= quantity <= 1000):
            raise ValueError("Quantity must be between 1 and 1000.")
        if not (0.01 <= price <= 1000):
            raise ValueError("Price must be between $0.01 and $1000.")
        if len(name) > 50:
            raise ValueError("Name must be a maximum of 50 characters.")

        self.items[name] = GroceryItem(name, quantity, price, nutritional_info)

    def remove_item(self, name):
        if name in self.items:
            del self.items[name]
        else:
            print(f"Item '{name}' not found in inventory.")

    def update_quantity(self, name, quantity):
        if not (1 <= quantity <= 1000):
            raise ValueError("Quantity must be between 1 and 1000.")
        if name in self.items:
            self.items[name].quantity = quantity
        else:
            print(f"Item '{name}' not found in inventory.")

    def update_price(self, name, price):
        if not (0.01 <= price <= 1000):
            raise ValueError("Price must be between $0.01 and $1000.")
        if name in self.items:
            self.items[name].price = price
        else:
            print(f"Item '{name}' not found in inventory.")

    def get_nutritional_information(self, name):
        if name in self.items:
            return self.items[name].nutritional_info
        else:
            print(f"Item '{name}' not found in inventory.")
            return None

    def __repr__(self):
        return f"Inventory(items={self.items})"

# Unit tests
def test_inventory():
    inventory = Inventory()

    # Test adding items
    nutritional_info1 = NutritionalInfo(200, 30.5, {'A': 1.2, 'C': 0.8})
    inventory.add_item("Apple", 100, 0.5, nutritional_info1)
    assert "Apple" in inventory.items

    # Test updating quantity
    inventory.update_quantity("Apple", 150)
    assert inventory.items["Apple"].quantity == 150

    # Test updating price
    inventory.update_price("Apple", 0.6)
    assert inventory.items["Apple"].price == 0.6

    # Test getting nutritional information
    assert inventory.get_nutritional_information("Apple") == nutritional_info1

    # Test removing item
    inventory.remove_item("Apple")
    assert "Apple" not in inventory.items

    # Test removing non-existent item
    inventory.remove_item("Banana")  # Should print a message

    # Test adding item with invalid data
    try:
        inventory.add_item("Banana", 2000, 0.5, nutritional_info1)
    except ValueError as e:
        assert str(e) == "Quantity must be between 1 and 1000."

    try:
        inventory.add_item("Cherry", 100, 1001, nutritional_info1)
    except ValueError as e:
        assert str(e) == "Price must be between $0.01 and $1000."

    try:
        inventory.add_item("Date" * 10, 100, 0.5, nutritional_info1)
    except ValueError as e:
        assert str(e) == "Name must be a maximum of 50 characters."

    print("All tests passed.")

test_inventory()
```

### Explanation:

1. **Classes**:
   - `NutritionalInfo`: Encapsulates nutritional details.
   - `GroceryItem`: Represents an item in the inventory with its attributes.
   - `Inventory`: Manages the collection of items using a dictionary for efficient operations.

2. **Operations**:
   - `add_item`: Adds a new item, checking constraints.
   - `remove_item`: Removes an item by name, handling non-existent items gracefully.
   - `update_quantity` and `update_price`: Update specific attributes, with checks.
   - `get_nutritional_information`: Retrieves nutritional info for a given item.

3. **Efficiency**:
   - The dictionary provides O(1) average time complexity for add, remove, and update operations.

4. **Unit Tests**:
   - Tests cover adding, updating, removing, and retrieving items, including edge cases and error handling.

