```python
def find_palindromic_substrings(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string.")

    def is_valid_palindrome(sub):
        # Check if the substring is a valid palindrome (not all characters are the same)
        return len(set(sub)) > 1

    def expand_around_center(left, right):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            if is_valid_palindrome(s[left:right+1]):
                palindromes.add(s[left:right+1])
            left -= 1
            right += 1

    palindromes = set()

    for i in range(len(s)):
        # Odd length palindromes
        expand_around_center(i, i)
        # Even length palindromes
        expand_around_center(i, i + 1)

    return palindromes

# Unit tests
def test_find_palindromic_substrings():
    assert find_palindromic_substrings("") == set()
    assert find_palindromic_substrings("a") == set()
    assert find_palindromic_substrings("aa") == set()
    assert find_palindromic_substrings("abba") == {"abba", "bb"}
    assert find_palindromic_substrings("abc") == set()
    assert find_palindromic_substrings("racecar") == {"racecar", "aceca", "cec"}
    assert find_palindromic_substrings("aabbbaa") == {"bb", "aabbaa", "abbba", "bbaab"}
    assert find_palindromic_substrings("aaaa") == set()
    assert find_palindromic_substrings("abacdfgdcaba") == {"aba", "aca", "bcb", "aba"}

    try:
        find_palindromic_substrings(123)
    except TypeError as e:
        assert str(e) == "Input must be a string."
    else:
        assert False, "TypeError not raised for non-string input"

# Run tests
