def is_rotation(string1: str, string2: str) -> bool:
    # Check if either string is empty or if their lengths are different
    if not string1 or not string2 or len(string1) != len(string2):
        return False

    # Concatenate string1 with itself
    concatenated = string1 + string1

    # Check if string2 is a substring of the concatenated string
    return string2 in concatenated

# Test cases
print(is_rotation("abcd", "cdab"))  # True
print(is_rotation("abc", "bcd"))    # False
print(is_rotation("a", "a"))        # True
print(is_rotation("abc", "cab"))    # True
print(is_rotation("abc", "acb"))    # False
print(is_rotation("", "abc"))       # False
print(is_rotation("abc", ""))       # False
print(is_rotation("abc", "def"))    # False
