            digit_count += 1
        elif char in "!@#$%^&*":
            special_char_count += 1

        # Check for consecutive identical characters
        if prev_char is not None and char == prev_char:
            return False

        # Check for consecutive alphabetical order
        if prev_char is not None:
            if char.isalpha() and prev_char.isalpha():
                if ord(char) == ord(prev_char) + 1 or ord(char) == ord(prev_char) - 1:
                    return False

        # Check for consecutive numerical order
        if prev_digit is not None and char.isdigit() and prev_digit.isdigit():
