import re
from datetime import datetime

class Person:
    MAX_HOBBIES = 10
    MAX_ADDRESSES = 5

    def __init__(self, name, age, hobbies, address):
        self.name = name
        self.age = self.validate_age(age)
        self.hobbies = self.validate_hobbies(hobbies)
        self.addresses = {}
        self.add_address("primary", address)
        self.current_year = datetime.now().year

    def validate_age(self, age):
        if isinstance(age, int) and age > 0:
            return age
        raise ValueError("Age must be a positive integer.")

    def validate_zip_code(self, zip_code, country="US"):
        if country == "US":
            return re.match(r'^\d{5}$', zip_code) is not None
        # Add more country-specific validations as needed
        return True

    def validate_address_component(self, component, max_length=50):
        if not component or not component.isalpha() or len(component) > max_length:
            raise ValueError(f"Invalid component: {component}. Must be non-empty, alphabetic, and <= {max_length} characters.")
        return component

    def validate_hobbies(self, hobbies):
        if not hobbies or not all(hobby.isalpha() for hobby in hobbies):
            raise ValueError("Hobbies must be non-empty and contain only alphabetic characters.")
        if len(hobbies) > self.MAX_HOBBIES:
            raise ValueError(f"Cannot have more than {self.MAX_HOBBIES} hobbies.")
        return hobbies

    def add_hobby(self, hobby):
        if hobby.isalpha():
            self.hobbies.append(hobby)
        else:
            raise ValueError("Hobby must contain only alphabetic characters.")

    def remove_hobby(self, hobby):
        if hobby in self.hobbies:
            self.hobbies.remove(hobby)

    def calculate_age_in_months(self):
        age_in_months = self.age * 12
        # Adjust for leap years
        leap_years = sum(1 for year in range(self.current_year - self.age, self.current_year) if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0))
        return age_in_months + leap_years

    def calculate_birth_year(self):
        birth_year = self.current_year - self.age
        if 1000 <= birth_year <= 9999:
            return birth_year
        raise ValueError("Invalid birth year calculated.")

    def add_address(self, identifier, address):
        if identifier in self.addresses:
            raise ValueError("Address identifier already exists.")
        if len(self.addresses) >= self.MAX_ADDRESSES:
            raise ValueError(f"Cannot have more than {self.MAX_ADDRESSES} addresses.")
        street, house_number, city, state, zip_code = address
        self.validate_address_component(street)
        self.validate_address_component(house_number, max_length=10)
        self.validate_address_component(city)
        self.validate_address_component(state)
        if not self.validate_zip_code(zip_code):
            raise ValueError("Invalid zip code format.")
        self.addresses[identifier] = {
            "street": street,
            "house_number": house_number,
            "city": city,
            "state": state,
            "zip_code": zip_code
        }

    def remove_address(self, identifier):
        if identifier in self.addresses:
            del self.addresses[identifier]

    def get_address(self, identifier):
        return self.addresses.get(identifier)

    def calculate_full_address(self, identifier):
        address = self.get_address(identifier)
        if address:
            full_address = f"{address['house_number']} {address['street']}, {address['city']}, {address['state']} {address['zip_code']}"
            if len(full_address) <= 200:
                return full_address
            raise ValueError("Full address exceeds maximum length.")
        return None

    def display_person_data(self):
        print(f"Name: {self.name.title()}")
        print(f"Age: {self.age}")
        print(f"Age in Months: {self.calculate_age_in_months()}")
        print(f"Birth Year: {self.calculate_birth_year()}")
        print(f"Hobbies: {', '.join(hobby.title() for hobby in self.hobbies)}")
        for identifier, address in self.addresses.items():
            print(f"Address ({identifier}): {self.calculate_full_address(identifier)}")

    def search_hobby(self, hobby):
        return any(hobby.lower() in h.lower() for h in self.hobbies)

# Example usage:
try:
    person = Person(
        name="John Doe",
        age=30,
        hobbies=["reading", "swimming"],
        address=("Main St", "123", "Springfield", "IL", "62701")
    )
    person.add_hobby("cycling")
    person.display_person_data()
    print("Hobby 'reading' found:", person.search_hobby("reading"))
    person.add_address("secondary", ("Second St", "456", "Shelbyville", "IL", "62702"))
    person.display_person_data()
except ValueError as e:
    print(e)
```

