import math

def transform_value(value):
    if isinstance(value, (int, float)):
        if math.isnan(value) or value < 0:
            return 0
        elif value > 0 and value % 2 == 0:
            return 1
        else:
            return value
    elif isinstance(value, str) and value == '':
        return 0
    elif value is None:
        return 0
    return value

def transform_structure(structure):
    if isinstance(structure, list):
        return [transform_structure(item) for item in structure]
    elif isinstance(structure, dict):
        return {key: transform_structure(value) for key, value in structure.items()}
    else:
        return transform_value(structure)

# Unit tests
def test_transform_structure():
    my_list = [5, -2, 3, None, '', 8]
    expected_list = [1, 0, 3, 0, 0, 1]
    assert transform_structure(my_list) == expected_list

    my_dict = {'a': 1, 'b': '', 'c': None, 'd': [1, '', None]}
    expected_dict = {'a': 1, 'b': 0, 'c': 0, 'd': [1, 0, 0]}
    assert transform_structure(my_dict) == expected_dict

    my_nested_list = [1, [2, '', [None]], {'a': '', 'b': [3, None, '']}]
    expected_nested_list = [1, [1, 0, [0]], {'a': 0, 'b': [3, 0, 0]}]
    assert transform_structure(my_nested_list) == expected_nested_list

    # Edge cases
    empty_list = []
    assert transform_structure(empty_list) == []

    empty_dict = {}
    assert transform_structure(empty_dict) == {}

    mixed_types = [5, "hello", None, [3.5, -1, "world"], {'key': 4, 'none': None}]
