```python
from datetime import datetime, timedelta
import random

class LivingBeing:
    def __init__(self, name):
        self.name = name

    def move(self):
        raise NotImplementedError("This method should be implemented by subclasses.")

class Animal(LivingBeing):
    species_lifespans = {
        'dog': 13,
        'cat': 15,
        'parrot': 50,
        'salmon': 5
    }
    valid_foods = {
        'dog': ['meat', 'vegetables'],
        'cat': ['fish', 'meat'],
        'parrot': ['seeds', 'fruit'],
        'salmon': ['algae', 'insects']
    }

    def __init__(self, name, species):
        super().__init__(name)
        self.species = species
        self.creation_date = datetime.now()
        self.age = 0

    @property
    def age(self):
        return self._calculate_age()

    @age.setter
    def age(self, value):
        self._age = value

    def _calculate_age(self):
        lifespan = self.get_average_lifespan()
        current_date = datetime.now()
        age_in_years = (current_date - self.creation_date).days / 365.25
        return min(age_in_years, lifespan)

    def eat(self, food):
        if food not in self.valid_foods[self.species]:
            raise ValueError(f"{self.name} cannot eat {food}.")
        nutritional_value = random.uniform(0.1, 0.5)
        self.age += nutritional_value / 10  # Simplified age update logic

    @staticmethod
    def compare_age(animal1, animal2):
        return animal1.age > animal2.age

    @staticmethod
    def get_average_lifespan(species):
        return Animal.species_lifespans.get(species, 0)

    def reproduce(self):
        return self.__class__(f"{self.name}'s offspring", self.species)

    def speak(self):
        raise NotImplementedError("This method should be implemented by subclasses.")

class Mammal(Animal):
    def __init__(self, name, species, fur_color):
        super().__init__(name, species)
        self.fur_color = fur_color

    def move(self):
        print(f"{self.name} is walking.")

    def milk(self):
        print(f"{self.name} is producing milk.")

    def speak(self):
        if self.species == 'dog':
            print("Woof!")
        elif self.species == 'cat':
            print("Meow!")
        else:
            print("Mammal sound.")

class Bird(Animal):
    def __init__(self, name, species, wing_span):
        super().__init__(name, species)
        self.wing_span = wing_span

    def move(self):
        print(f"{self.name} is flying.")

    def fly(self):
        print(f"{self.name} is soaring through the sky.")

    def speak(self):
        if self.species == 'parrot':
            print("Squawk!")
        else:
            print("Bird sound.")

class Fish(Animal):
    def __init__(self, name, species, water_type):
        super().__init__(name, species)
        self.water_type = water_type

    def move(self):
        print(f"{self.name} is swimming.")

    def swim(self):
        print(f"{self.name} is gliding through the water.")

    def speak(self):
        print("Fish sound.")

# Example usage
dog = Mammal("Buddy", "dog", "brown")
cat = Mammal("Whiskers", "cat", "black")
parrot = Bird("Polly", "parrot", 1.5)
salmon = Fish("Nemo", "salmon", "freshwater")

dog.eat("meat")
cat.eat("fish")
parrot.eat("seeds")
salmon.eat("algae")

print(f"{dog.name} is {dog.age:.2f} years old.")
print(f"{cat.name} is {cat.age:.2f} years old.")
print(f"{parrot.name} is {parrot.age:.2f} years old.")
print(f"{salmon.name} is {salmon.age:.2f} years old.")

offspring = dog.reproduce()
print(f"{offspring.name} is a {offspring.species} with {offspring.fur_color} fur.")

dog.speak()
cat.speak()
parrot.speak()
salmon.speak()

