    def set_sound(self, sound):
        self.sound = sound

    def set_weight(self, weight):
        self.weight = weight

    def set_color(self, color):
        self.color = color

    def make_sound(self):
        print(self.sound)


class Dog(Animal):
    def bark(self):
        print("Woof! Woof!")

    def eat(self):
        if self.age < 2:
            self.weight += 0.5
        else:
            self.weight += 0.3

    def get_weight(self):
        return self.weight * 2


class Cat(Animal):
    def meow(self):
        print("Meow! Meow!")

    def eat(self):
        if self.age < 1:
            self.weight += 0.2
        else:
            self.weight += 0.1

    def get_weight(self):
        return self.weight / 2


