```python
import pandas as pd

def determine_relationship(df, col1, col2):
    # Get unique values and their counts for each column
    unique_col1 = df[col1].value_counts()
    unique_col2 = df[col2].value_counts()

    # Check if each value in col1 maps to a unique value in col2
    one_to_one = True
    one_to_many = False
    many_to_one = False
    many_to_many = False

    for val1 in unique_col1.index:
        # Get all corresponding values in col2
        corresponding_values = df[df[col1] == val1][col2].unique()

        if len(corresponding_values) > 1:
            one_to_one = False
            one_to_many = True
        elif len(corresponding_values) == 1:
            val2 = corresponding_values[0]
            if unique_col2[val2] > 1:
                many_to_one = True
            else:
                one_to_one = one_to_one and True

    # Check if each value in col2 maps to a unique value in col1
    for val2 in unique_col2.index:
        # Get all corresponding values in col1
        corresponding_values = df[df[col2] == val2][col1].unique()

        if len(corresponding_values) > 1:
            one_to_one = False
            many_to_one = True
        elif len(corresponding_values) == 1:
            val1 = corresponding_values[0]
            if unique_col1[val1] > 1:
                one_to_many = True
            else:
                one_to_one = one_to_one and True

    if one_to_one:
        return "one-2-one"
    elif one_to_many and many_to_one:
        return "many-2-many"
    elif one_to_many:
        return "one-2-many"
    elif many_to_one:
        return "many-2-one"
    else:
        return "many-2-many"

def relationship_matrix(df):
    columns = df.columns
    result = pd.DataFrame(index=columns, columns=columns, dtype=object)

    for col1 in columns:
        for col2 in columns:
            if col1 == col2:
                result.at[col1, col2] = "one-2-one"
            else:
                result.at[col1, col2] = determine_relationship(df, col1, col2)

