Below is a self-contained Flask application that implements user authentication using Flask-Login, Flask-WTF, and Werkzeug for password hashing. It includes routes for login, logout, and a protected page, along with measures to prevent brute-force attacks by limiting login attempts.

```python
from flask import Flask, render_template, redirect, url_for, flash
from flask_login import LoginManager, UserMixin, login_user, login_required, logout_user, current_user
from flask_wtf import FlaskForm
from wtforms import StringField, PasswordField, SubmitField
from wtforms.validators import DataRequired, Length
from werkzeug.security import generate_password_hash, check_password_hash
from flask_limiter import Limiter
from flask_limiter.util import get_remote_address

# Define a simple User class
class User(UserMixin):
    def __init__(self, id, username, password_hash):
        self.id = id
        self.username = username
        self.password_hash = password_hash

# In-memory user store
users = {
    "user1": User(id=1, username="user1", password_hash=generate_password_hash("password123"))
}

# Define the login form
class LoginForm(FlaskForm):
    username = StringField('Username', validators=[DataRequired(), Length(min=4, max=25)])
    password = PasswordField('Password', validators=[DataRequired(), Length(min=8, max=80)])
    submit = SubmitField('Log In')

# Initialize Flask app and login manager
def task_func(secret_key, template_folder):
    app = Flask(__name__)
    app.config['SECRET_KEY'] = secret_key
    app.config['TEMPLATES_AUTO_RELOAD'] = True
    app.config['TEMPLATES_FOLDER'] = template_folder

    login_manager = LoginManager()
    login_manager.init_app(app)
    login_manager.login_view = 'login'

    # Initialize rate limiter
    limiter = Limiter(
        get_remote_address,
        app=app,
        default_limits=["5 per minute"]
    )

    @login_manager.user_loader
    def load_user(user_id):
        for user in users.values():
            if user.id == int(user_id):
                return user
        return None

    @app.route('/login', methods=['GET', 'POST'])
    @limiter.limit("5 per minute")
    def login():
        form = LoginForm()
        if form.validate_on_submit():
            user = next((u for u in users.values() if u.username == form.username.data), None)
            if user and check_password_hash(user.password_hash, form.password.data):
                login_user(user)
                return redirect(url_for('protected'))
            else:
                flash('Invalid username or password', 'danger')
        return render_template('login.html', form=form)

    @app.route('/logout')
    @login_required
    def logout():
        logout_user()
        return redirect(url_for('login'))

    @app.route('/protected')
    @login_required
    def protected():
        return f'Hello, {current_user.username}! This is a protected page.'

    return app

# Example usage
if __name__ == '__main__':
    app = task_func('your_secret_key', 'templates')
    app.run(debug=True)
```

### Key Features:
- **User Authentication**: Uses Flask-Login for session management.
- **Password Security**: Passwords are hashed using Werkzeug's `generate_password_hash`.
- **Rate Limiting**: Flask-Limiter is used to prevent brute-force attacks by limiting login attempts.
- **User Feedback**: Provides clear error messages for invalid login attempts.
- **Protected Route**: Only accessible to authenticated users.

### Templates:
You need to create a `login.html` template in the `templates` directory to render the login form. Here's a simple example:

```html
