To generate a DataFrame with the specified requirements, we need to ensure that each column contains data of a specific type, and that all required types are represented at least once. We'll use Python's `random` module to generate the data and seed it for reproducibility. Here's how you can implement the function:

```python
import pandas as pd
import numpy as np
from random import choice, randint, seed, sample

# Constants
DATA_TYPES = [str, int, float, list, tuple, dict, set]

def generate_random_data(data_type):
    if data_type == str:
        return ''.join(choice('abcdefghijklmnopqrstuvwxyz') for _ in range(5))
    elif data_type == int:
        return randint(0, 9)
    elif data_type == float:
        return float(randint(0, 9))
    elif data_type == list:
        return [randint(0, 9) for _ in range(randint(1, 5))]
    elif data_type == tuple:
        return tuple(randint(0, 9) for _ in range(randint(1, 5)))
    elif data_type == dict:
        return {randint(0, 9): randint(0, 9) for _ in range(randint(1, 5))}
    elif data_type == set:
        return set(sample(range(10), randint(1, 5)))
    else:
        raise ValueError(f"Unsupported data type: {data_type}")

def task_func(rows, columns, seed_value=42):
    if rows < 1 or columns < 1:
        raise ValueError("Number of rows and columns must be at least 1.")

    # Seed the random number generator for reproducibility
    seed(seed_value)

    # Ensure each data type is used at least once
    if columns < len(DATA_TYPES):
        raise ValueError("Number of columns must be at least 7 to include all data types.")

    # Randomly assign data types to columns, ensuring all types are used
    column_types = choice(DATA_TYPES) + [choice(DATA_TYPES) for _ in range(columns - 1)]
    np.random.shuffle(column_types)

    # Create the DataFrame
    data = {f'col{i}': [generate_random_data(column_types[i]) for _ in range(rows)] for i in range(columns)}
    df = pd.DataFrame(data)

    return df

# Example usage
df = task_func(10, 7)
print(df)
```

