```python
class MassEditManager:
    def __init__(self):
        self.templates = {}
        self.sidebar_actions = {}

    def create_template(self, name, model):
        if name in self.templates:
            raise ValueError(f"Template name '{name}' already exists.")
        self.templates[name] = {
            'model': model,
            'editing_lines': []
        }

    def add_editing_line(self, template_name, field, new_value):
        if template_name not in self.templates:
            raise KeyError(f"Template '{template_name}' does not exist.")
        self.templates[template_name]['editing_lines'].append({
            'field': field,
            'new_value': new_value
        })

    def create_sidebar_action(self, template_name):
        if template_name not in self.templates:
            raise KeyError(f"Template '{template_name}' does not exist.")
        action_name = f"Sidebar_{template_name}"
        self.sidebar_actions[action_name] = {
            'template_name': template_name,
            'model': self.templates[template_name]['model']
        }

    def delete_sidebar_action(self, action_name):
        if action_name not in self.sidebar_actions:
            raise KeyError(f"Sidebar action '{action_name}' does not exist.")
        del self.sidebar_actions[action_name]

    def delete_template(self, template_name):
        if template_name not in self.templates:
            raise KeyError(f"Template '{template_name}' does not exist.")
        # Remove associated sidebar actions
        for action_name, action in list(self.sidebar_actions.items()):
            if action['template_name'] == template_name:
                del self.sidebar_actions[action_name]
        del self.templates[template_name]

    def copy_template(self, original_name, new_name):
        if original_name not in self.templates:
            raise KeyError(f"Template '{original_name}' does not exist.")
        if new_name in self.templates:
            raise ValueError(f"Template name '{new_name}' already exists.")
        self.templates[new_name] = {
            'model': self.templates[original_name]['model'],
            'editing_lines': self.templates[original_name]['editing_lines'][:]
        }

    def get_applicable_records(self, template_name, model):
