To design a simple mathematical expression parser and evaluator with the specified features, we can create a class `Runtime` that handles variable assignments, function definitions, and arithmetic operations. We'll use Python's `eval` function cautiously to evaluate expressions, and we'll manage the scope of variables and functions using dictionaries. Here's a basic implementation:

```python
import math
import re

class Runtime:
    def __init__(self):
        self.variables = {}
        self.functions = {
            'sin': math.sin,
            'cos': math.cos,
            'tan': math.tan,
            'asin': math.asin,
            'acos': math.acos,
            'atan': math.atan
        }

    def execute(self, statement):
        try:
            if '=' in statement:
                self.handle_assignment(statement)
            elif ':' in statement:
                self.handle_function_definition(statement)
            else:
                result = self.evaluate_expression(statement)
                print(f"Result: {result}")
        except Exception as e:
            print(f"Error: {e}")

    def handle_assignment(self, statement):
        var, expr = map(str.strip, statement.split('=', 1))
        self.variables[var] = self.evaluate_expression(expr)

    def handle_function_definition(self, statement):
        func_def, expr = map(str.strip, statement.split(':', 1))
        func_name, params = self.parse_function_definition(func_def)
        self.functions[func_name] = (params, expr)

    def parse_function_definition(self, func_def):
        match = re.match(r'(\w+)\(([^)]*)\)', func_def)
        if not match:
            raise ValueError("Invalid function definition")
        func_name, param_str = match.groups()
        params = [p.strip() for p in param_str.split(',')]
        return func_name, params

    def evaluate_expression(self, expr):
        # Replace variables with their values
        for var in self.variables:
            expr = re.sub(r'\b' + re.escape(var) + r'\b', str(self.variables[var]), expr)

        # Evaluate the expression
        return self.safe_eval(expr)

    def safe_eval(self, expr):
        # Allow only safe operations
        allowed_names = {name: obj for name, obj in self.functions.items()}
        allowed_names.update(self.variables)
        allowed_names.update({k: getattr(math, k) for k in dir(math) if not k.startswith('_')})

        code = compile(expr, "<string>", "eval")
        for name in code.co_names:
            if name not in allowed_names:
                raise NameError(f"Use of undefined variable or function '{name}'")

        return eval(code, {"__builtins__": {}}, allowed_names)

    def call_function(self, func_name, *args):
        if func_name not in self.functions:
            raise NameError(f"Function '{func_name}' is not defined")

        params, expr = self.functions[func_name]
        if len(args) != len(params):
            raise ValueError(f"Function '{func_name}' expects {len(params)} arguments, got {len(args)}")

        local_vars = dict(zip(params, args))
        local_vars.update(self.variables)

        # Replace parameters with arguments in the expression
        for param, arg in local_vars.items():
            expr = re.sub(r'\b' + re.escape(param) + r'\b', str(arg), expr)

        return self.safe_eval(expr)

    def interactive_shell(self):
        print("Interactive shell. Type 'exit()' to quit.")
        while True:
            try:
                statement = input(">>> ")
                if statement.strip() == "exit()":
                    break
                self.execute(statement)
            except Exception as e:
                print(f"Error: {e}")

    def list_variables(self):
        print("Variables:")
        for var, value in self.variables.items():
            print(f"{var} = {value}")

    def list_functions(self):
        print("Functions:")
        for func in self.functions:
            print(func)

# Example usage
runtime = Runtime()
runtime.interactive_shell()
```

### Key Features:
- **Variable Assignment**: Handles assignments like `x = 3.5`.
- **Function Definition**: Supports defining functions with parameters, e.g., `f(x,y):x+y`.
- **Expression Evaluation**: Evaluates arithmetic expressions with support for parentheses.
- **Built-in Functions**: Includes `sin`, `cos`, `tan`, `asin`, `acos`, `atan`.
- **Error Handling**: Gracefully handles undefined variables or functions.
- **Interactive Shell**: Allows users to input commands, list variables/functions, and exit.

This implementation provides a basic framework for a mathematical expression parser and evaluator. It can be extended with more features and improved error handling as needed.

