```python
from typing import List, Dict, Any

class Queue:
    def __init__(self, queue_id: str, penalty: int):
        self.queue_id = queue_id
        self.penalty = penalty

    def __eq__(self, other):
        if isinstance(other, Queue):
            return self.queue_id == other.queue_id
        return False

    def __hash__(self):
        return hash(self.queue_id)

class QueueDelta:
    def calculate(self, old_queues: List[Queue], new_queues: List[Queue]) -> Dict[str, List[Queue]]:
        if not isinstance(old_queues, list) or not isinstance(new_queues, list):
            raise ValueError("Both old_queues and new_queues must be lists.")

        if not all(isinstance(queue, Queue) for queue in old_queues + new_queues):
            raise ValueError("All elements in old_queues and new_queues must be instances of Queue.")

        old_dict = {queue.queue_id: queue for queue in old_queues}
        new_dict = {queue.queue_id: queue for queue in new_queues}

        added = [queue for queue in new_queues if queue.queue_id not in old_dict]
        removed = [queue for queue in old_queues if queue.queue_id not in new_dict]
        penalty_updated = [
            new_dict[queue_id] for queue_id in new_dict
            if queue_id in old_dict and new_dict[queue_id].penalty != old_dict[queue_id].penalty
        ]

        return {
            'added': added,
            'removed': removed,
            'penalty_updated': penalty_updated
        }

class OnAgentUpdatedManager:
    def __init__(self, add_to_queue_action, remove_from_queue_action, update_penalty_action):
        self.add_to_queue_action = add_to_queue_action
        self.remove_from_queue_action = remove_from_queue_action
        self.update_penalty_action = update_penalty_action

    def on_agent_updated(self, agent: Dict[str, Any]):
        if not isinstance(agent, dict):
            raise ValueError("Agent must be a dictionary.")

        required_keys = {'agent_id', 'old_queues', 'new_queues'}
        if not required_keys.issubset(agent.keys()):
            raise ValueError(f"Agent dictionary must contain keys: {required_keys}")

        old_queues = agent['old_queues']
        new_queues = agent['new_queues']

        queue_delta = QueueDelta()
        changes = queue_delta.calculate(old_queues, new_queues)

        for queue in changes['added']:
            self.add_to_queue_action(agent['agent_id'], queue)

        for queue in changes['removed']:
            self.remove_from_queue_action(agent['agent_id'], queue)

        for queue in changes['penalty_updated']:
            self.update_penalty_action(agent['agent_id'], queue)

# Mock action handlers
def add_to_queue_action(agent_id, queue):
    print(f"Agent {agent_id} added to queue {queue.queue_id}")

def remove_from_queue_action(agent_id, queue):
    print(f"Agent {agent_id} removed from queue {queue.queue_id}")

def update_penalty_action(agent_id, queue):
    print(f"Agent {agent_id} penalty updated in queue {queue.queue_id}")

# Example usage
if __name__ == "__main__":
    old_queues = [Queue("queue1", 10), Queue("queue2", 5)]
    new_queues = [Queue("queue1", 10), Queue("queue3", 7)]

    agent = {
        'agent_id': 'agent_123',
        'old_queues': old_queues,
        'new_queues': new_queues
    }

    manager = OnAgentUpdatedManager(add_to_queue_action, remove_from_queue_action, update_penalty_action)
    manager.on_agent_updated(agent)
```

