```python
def string_operations(s, operations):
    def slice_operation(start, end):
        try:
            return s[start:end]
        except IndexError:
            return ""

    def check_operation(sub):
        return sub in s

    def concat_operation(str_to_add):
        return s + str_to_add

    def format_operation(values):
        placeholders = s.count("{}")
        if placeholders != len(values):
            raise ValueError("Number of placeholders does not match number of values.")
        return s.format(*values)

    operation_map = {
        "slice": slice_operation,
        "check": check_operation,
        "concat": concat_operation,
        "format": format_operation
    }

    results = []

    for operation in operations:
        if not isinstance(operation, tuple) or len(operation) < 2:
            raise ValueError("Each operation must be a tuple with at least an operation name and parameters.")

        op_name = operation[0]
        params = operation[1:]

        if op_name not in operation_map:
            raise ValueError(f"Unsupported operation: {op_name}")

        try:
            if op_name == "format":
                result = operation_map[op_name](params)
            else:
                result = operation_map[op_name](*params)
            results.append(result)
        except Exception as e:
            raise ValueError(f"Error in operation {op_name}: {str(e)}")

    return results

# Unit tests
def test_string_operations():
    # Test slicing
    assert string_operations("hello", [("slice", 1, 3)]) == ["el"]
    assert string_operations("hello", [("slice", 0, 10)]) == ["hello"]
    assert string_operations("hello", [("slice", 10, 15)]) == [""]
    assert string_operations("", [("slice", 0, 1)]) == [""]

    # Test check
    assert string_operations("hello", [("check", "ell")]) == [True]
    assert string_operations("hello", [("check", "world")]) == [False]
    assert string_operations("", [("check", "anything")]) == [False]

    # Test concat
    assert string_operations("hello", [("concat", " world")]) == ["hello world"]
    assert string_operations("", [("concat", "world")]) == ["world"]

    # Test format
    assert string_operations("Hello, {}!", [("format", ["world"])]) == ["Hello, world!"]
    assert string_operations("Value: {}", [("format", [42])]) == ["Value: 42"]
    try:
        string_operations("Hello, {}!", [("format", ["world", "extra"])])
    except ValueError as e:
        assert str(e) == "Number of placeholders does not match number of values."

    # Test invalid operations
    try:
        string_operations("test", [("invalid_op",)])
    except ValueError as e:
        assert str(e) == "Unsupported operation: invalid_op"

    try:
        string_operations("test", [("slice",)])
    except ValueError as e:
        assert str(e) == "Each operation must be a tuple with at least an operation name and parameters."

    print("All tests passed.")

# Run tests
test_string_operations()
