To implement Conway's Game of Life using Pygame, we'll create a Python program that includes a grid of cells, allows for manual configuration of the initial state, and simulates the game according to its rules. We'll also include a simple menu for user interaction. Below is a complete implementation of the program:

```python
import pygame
import sys

# Constants
CELL_SIZE = 10
GRID_WIDTH = 50
GRID_HEIGHT = 50
WINDOW_WIDTH = GRID_WIDTH * CELL_SIZE
WINDOW_HEIGHT = GRID_HEIGHT * CELL_SIZE
FPS = 10

# Colors
WHITE = (255, 255, 255)
BLACK = (0, 0, 0)

# Initialize Pygame
pygame.init()
screen = pygame.display.set_mode((WINDOW_WIDTH, WINDOW_HEIGHT))
pygame.display.set_caption("Conway's Game of Life")
clock = pygame.time.Clock()

# Grid
grid = [[False for _ in range(GRID_WIDTH)] for _ in range(GRID_HEIGHT)]

def draw_grid():
    for y in range(GRID_HEIGHT):
        for x in range(GRID_WIDTH):
            rect = pygame.Rect(x * CELL_SIZE, y * CELL_SIZE, CELL_SIZE, CELL_SIZE)
            color = WHITE if grid[y][x] else BLACK
            pygame.draw.rect(screen, color, rect)
            pygame.draw.rect(screen, BLACK, rect, 1)

def toggle_cell(x, y):
    grid[y][x] = not grid[y][x]

def count_neighbors(x, y):
    neighbors = 0
    for dy in [-1, 0, 1]:
        for dx in [-1, 0, 1]:
            if dx == 0 and dy == 0:
                continue
            nx, ny = x + dx, y + dy
            if 0 <= nx < GRID_WIDTH and 0 <= ny < GRID_HEIGHT:
                neighbors += grid[ny][nx]
    return neighbors

def update_grid():
    new_grid = [[False for _ in range(GRID_WIDTH)] for _ in range(GRID_HEIGHT)]
    for y in range(GRID_HEIGHT):
        for x in range(GRID_WIDTH):
            neighbors = count_neighbors(x, y)
            if grid[y][x]:
                if neighbors < 2 or neighbors > 3:
                    new_grid[y][x] = False
                else:
                    new_grid[y][x] = True
            else:
                if neighbors == 3:
                    new_grid[y][x] = True
    return new_grid

def main_menu():
    menu_options = ["Configure Cells Manually", "Start the Game"]
    selected_option = 0

    while True:
        screen.fill(BLACK)
        for i, option in enumerate(menu_options):
            color = WHITE if i == selected_option else (100, 100, 100)
            font = pygame.font.Font(None, 36)
            text = font.render(option, True, color)
            text_rect = text.get_rect(center=(WINDOW_WIDTH // 2, 100 + i * 50))
            screen.blit(text, text_rect)

        pygame.display.flip()

        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                pygame.quit()
                sys.exit()
            elif event.type == pygame.KEYDOWN:
                if event.key == pygame.K_UP:
                    selected_option = (selected_option - 1) % len(menu_options)
                elif event.key == pygame.K_DOWN:
                    selected_option = (selected_option + 1) % len(menu_options)
                elif event.key == pygame.K_RETURN:
                    return selected_option

def main():
    running = True
    game_running = False
    menu_option = main_menu()

    while running:
        if menu_option == 0:
            screen.fill(BLACK)
            draw_grid()
            pygame.display.flip()

            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    running = False
                elif event.type == pygame.MOUSEBUTTONDOWN and not game_running:
                    x, y = pygame.mouse.get_pos()
                    grid_x, grid_y = x // CELL_SIZE, y // CELL_SIZE
                    if 0 <= grid_x < GRID_WIDTH and 0 <= grid_y < GRID_HEIGHT:
                        toggle_cell(grid_x, grid_y)

        elif menu_option == 1:
            game_running = True
            while game_running:
                screen.fill(BLACK)
                draw_grid()
                pygame.display.flip()

                for event in pygame.event.get():
                    if event.type == pygame.QUIT:
                        running = False
                        game_running = False

                grid = update_grid()
                clock.tick(FPS)

        menu_option = main_menu()

    pygame.quit()
    sys.exit()

if __name__ == "__main__":
    main()
```

### Explanation:

1. **Initialization**: We set up the Pygame window and define constants for the grid size, cell size, and colors.

2. **Grid Management**: The grid is a 2D list of booleans representing alive (True) or dead (False) cells.

3. **Drawing**: The `draw_grid` function draws the grid on the screen, using white for alive cells and black for dead cells.

4. **Cell Toggling**: The `toggle_cell` function changes the state of a cell when clicked.

5. **Neighbor Counting**: The `count_neighbors` function counts the alive neighbors of a cell.

6. **Grid Update**: The `update_grid` function applies the Game of Life rules to generate the next state of the grid.

7. **Menu System**: The `main_menu` function displays a simple menu for selecting options.

8. **Main Loop**: The `main` function handles the main game loop, switching between configuration and simulation modes based on user input.

This program allows users to configure the initial state of the grid and then start the simulation, updating the grid at a consistent rate.

