```python
import os
import json

class Response:
    def __init__(self):
        self.success = True
        self.message = ""
        self.recent_paths = []

    def set_success(self, success, message=""):
        self.success = success
        self.message = message

    def add_recent_path(self, path):
        if path not in self.recent_paths:
            self.recent_paths.append(path)

    def __str__(self):
        return f"Success: {self.success}, Message: {self.message}, Recent Paths: {self.recent_paths}"

class ProjectOpener:
    def project_exists(self, path):
        return os.path.exists(path) and os.path.isdir(path)

    def load_project(self, response, path):
        try:
            project_file = os.path.join(path, "project.json")
            if not os.path.exists(project_file):
                response.set_success(False, "Project file not found.")
                return False

            with open(project_file, 'r') as file:
                project_data = json.load(file)
            return True
        except Exception as e:
            response.set_success(False, f"Failed to load project: {str(e)}")
            return False

    def open_project(self, path, forget=False):
        response = Response()
        if not self.project_exists(path):
            response.set_success(False, "Project does not exist.")
            return response

        if not self.load_project(response, path):
            return response

        try:
            self.initialize_results(response, path)
        except Exception as e:
            response.set_success(False, f"Initialization error: {str(e)}")
            return response

        if not forget:
            response.add_recent_path(path)

        return response

    def initialize_results(self, response, project):
        results_path = os.path.join(project, "results")
        if not os.path.exists(results_path):
            os.makedirs(results_path)
        # Simulate some initialization logic
        # For example, create a default results file
        default_results_file = os.path.join(results_path, "default_results.txt")
        with open(default_results_file, 'w') as file:
            file.write("Default results initialized.")

# Unit tests
import unittest

class TestProjectOpener(unittest.TestCase):
    def setUp(self):
        self.project_opener = ProjectOpener()
        self.test_project_path = "test_project"
        os.makedirs(self.test_project_path, exist_ok=True)
        with open(os.path.join(self.test_project_path, "project.json"), 'w') as file:
            json.dump({"name": "Test Project"}, file)

    def tearDown(self):
        if os.path.exists(self.test_project_path):
            for root, dirs, files in os.walk(self.test_project_path, topdown=False):
                for name in files:
                    os.remove(os.path.join(root, name))
                for name in dirs:
                    os.rmdir(os.path.join(root, name))
            os.rmdir(self.test_project_path)

    def test_project_exists(self):
        self.assertTrue(self.project_opener.project_exists(self.test_project_path))
        self.assertFalse(self.project_opener.project_exists("non_existent_project"))

    def test_load_project_success(self):
        response = Response()
        self.assertTrue(self.project_opener.load_project(response, self.test_project_path))
        self.assertTrue(response.success)

    def test_load_project_failure(self):
        response = Response()
        self.assertFalse(self.project_opener.load_project(response, "non_existent_project"))
        self.assertFalse(response.success)

    def test_open_project_success(self):
        response = self.project_opener.open_project(self.test_project_path)
        self.assertTrue(response.success)
        self.assertIn(self.test_project_path, response.recent_paths)

    def test_open_project_non_existent(self):
        response = self.project_opener.open_project("non_existent_project")
        self.assertFalse(response.success)

    def test_open_project_load_failure(self):
        non_existent_project_path = "non_existent_project"
        os.makedirs(non_existent_project_path, exist_ok=True)
        response = self.project_opener.open_project(non_existent_project_path)
        self.assertFalse(response.success)
        os.rmdir(non_existent_project_path)

    def test_initialize_results(self):
        response = Response()
        self.project_opener.initialize_results(response, self.test_project_path)
        self.assertTrue(response.success)
        self.assertTrue(os.path.exists(os.path.join(self.test_project_path, "results", "default_results.txt")))

if __name__ == "__main__":
    unittest.main()
