def get_positive_integer(prompt):
    """Prompt the user for a positive integer and handle invalid inputs."""
    while True:
        try:
            value = int(input(prompt))
            if value < 0:
                print("Please enter a positive integer or 0 to finish.")
            else:
                return value
        except ValueError:
            print("Invalid input. Please enter a valid positive integer.")

def main():
    print("Enter positive integer values one by one.")
    print("Enter 0 to finish and calculate the average.")

    values = []

    while True:
        if not values:
            # Ensure the first value is not 0
            value = get_positive_integer("Enter the first positive integer (not 0): ")
            if value == 0:
                print("Error: The first value cannot be 0. Please start again.")
                continue
        else:
            value = get_positive_integer("Enter a positive integer (or 0 to finish): ")

        if value == 0:
            break
        values.append(value)

    if values:
        average = sum(values) / len(values)
        print(f"The average of the entered values is: {average:.2f}")
    else:
        print("No values were entered.")

if __name__ == "__main__":
    main()
