# Configure logging
logging.basicConfig(level=logging.DEBUG)
logger = logging.getLogger(__name__)

def unix_to_human_readable(unix_timestamp_str, separator=' '):
    """Convert a Unix timestamp string to a human-readable time string with a custom separator."""
    try:
        timestamp = int(unix_timestamp_str)
        return datetime.utcfromtimestamp(timestamp).strftime('%Y-%m-%d' + separator + '%H:%M:%S')
    except (ValueError, TypeError) as e:
        logger.debug(f"Error converting Unix timestamp to human-readable: {e}")
        raise ValueError("Invalid Unix timestamp string")

def human_readable_to_unix(human_readable_str, separator=' '):
    """Convert a human-readable time string with a custom separator to a Unix epoch timestamp."""
    try:
        dt = datetime.strptime(human_readable_str, '%Y-%m-%d' + separator + '%H:%M:%S')
        return int(time.mktime(dt.timetuple()))
    except (ValueError, TypeError) as e:
        logger.debug(f"Error converting human-readable time to Unix timestamp: {e}")
        raise ValueError("Invalid human-readable time string")

def get_start_end_of_day_unix():
    """Calculate the Unix timestamps for the start and end of the current day (00:00:00 to 23:59:59)."""
    now = datetime.utcnow()
    start_of_day = datetime(now.year, now.month, now.day)
    end_of_day = start_of_day + timedelta(days=1) - timedelta(seconds=1)
    return int(time.mktime(start_of_day.timetuple())), int(time.mktime(end_of_day.timetuple()))

def clean_ids(raw_data):
    """Clean up device and module IDs in the raw data by removing any superfluous spaces."""
    if isinstance(raw_data, dict):
        return {k.strip(): v.strip() if isinstance(v, str) else v for k, v in raw_data.items()}
    elif isinstance(raw_data, list):
        return [clean_ids(item) for item in raw_data]
    return raw_data

def extract_data_from_response(response):
    """Extract raw data from a server response, handling different tags and potential errors."""
    data = {}
    errors = []

    try:
        if 'data' not in response:
            raise NoDevice("No data found in response")

        raw_data = response['data']
        if not raw_data:
            raise NoDevice("No device data available")

        # Example of extracting specific fields, adjust as needed
        data['device_id'] = raw_data.get('device_id', '').strip()
        data['module_id'] = raw_data.get('module_id', '').strip()
        data['status'] = raw_data.get('status', '').strip()

        # Clean up IDs
        data = clean_ids(data)

        if not data['device_id'] or not data['module_id']:
            raise NoDevice("Device or module ID is missing or invalid")

    except KeyError as e:
        logger.debug(f"Key error while extracting data: {e}")
        errors.append(f"Missing key: {e}")
    except NoDevice as e:
        logger.debug(f"No device data error: {e}")
        errors.append(str(e))
    except Exception as e:
        logger.debug(f"Unexpected error: {e}")
        errors.append(f"Unexpected error: {e}")

    return {'data': data, 'errors': errors}

# Example usage
if __name__ == "__main__":
    # Example server response
    response = {
        "data": {
            "device_id": " 12345 ",
            "module_id": " 67890 ",
            "status": " active "
        }
    }

    result = extract_data_from_response(response)
    print(result)
