def get_primes(n):
    """Generate a list of prime numbers up to n using the Sieve of Eratosthenes."""
    is_prime = [True] * (n + 1)
    p = 2
    while (p * p <= n):
        if is_prime[p]:
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
        p += 1
    prime_numbers = [p for p in range(2, n + 1) if is_prime[p]]
    return prime_numbers

def is_prime(num, primes):
    """Check if a number is prime using a precomputed list of primes."""
    if num < 2:
        return False
    for prime in primes:
        if prime * prime > num:
            break
        if num % prime == 0:
            return False
    return True

def min_elements_to_remove(data):
    total_sum = sum(data)
    primes = get_primes(total_sum)

    # If the total sum is already a prime number, return no removals
    if is_prime(total_sum, primes):
        return (0, [])

    n = len(data)

    # Try removing elements and check if the remaining sum is prime
    for r in range(1, n + 1):
        for indices in combinations(range(n), r):
            current_sum = total_sum - sum(data[i] for i in indices)
            if is_prime(current_sum, primes):
                # Return the number of elements to remove and their 1-based indices
                return (r, [i + 1 for i in indices])

    # If no solution is found, return (-1, [])
    return (-1, [])

