To create an AWS Lambda function that processes S3 object creation events using AWS Lambda Powertools, you'll need to set up the function to handle S3 events, log details, trace execution, and record metrics. Below is a complete implementation of the Lambda function along with unit tests.

### Lambda Function

```python
import json
import logging
import boto3
from aws_lambda_powertools import Logger, Tracer, Metrics
from aws_lambda_powertools.metrics import MetricUnit

# Initialize AWS Lambda Powertools
logger = Logger()
tracer = Tracer()
metrics = Metrics()

# Initialize S3 client
s3_client = boto3.client('s3')

@tracer.capture_lambda_handler
@logger.inject_lambda_context(log_event=True)
@metrics.log_metrics(capture_cold_start_metric=True)
def lambda_handler(event, context):
    try:
        # Extract bucket name and object key from the event
        bucket_name = event['Records'][0]['s3']['bucket']['name']
        object_key = event['Records'][0]['s3']['object']['key']

        # Retrieve the object from S3
        response = s3_client.get_object(Bucket=bucket_name, Key=object_key)
        content = response['Body'].read().decode('utf-8')

        # Log the content for debugging
        logger.info(f"Content of the S3 object: {content}")

        # Record a custom metric
        metrics.add_metric(name="S3ObjectProcessed", unit=MetricUnit.Count, value=1)

        # Return the content and event details
        return {
            'statusCode': 200,
            'body': json.dumps({
                'content': content,
                'event': event
            })
        }

    except KeyError as e:
        logger.error(f"Missing key in event: {e}")
        return {
            'statusCode': 400,
            'body': json.dumps({'error': 'Invalid event structure'})
        }
    except s3_client.exceptions.NoSuchKey:
        logger.error(f"S3 object not found: {object_key} in bucket: {bucket_name}")
        return {
            'statusCode': 404,
            'body': json.dumps({'error': 'S3 object not found'})
        }
    except Exception as e:
        logger.error(f"An error occurred: {e}")
        return {
            'statusCode': 500,
            'body': json.dumps({'error': 'Internal server error'})
        }

```

