    assert response['statusCode'] == 400
    assert json.loads(response['body'])['error'] == 'Invalid event structure'

def test_s3_object_not_found(s3_setup):
    # Create a mock S3 bucket
    s3_client = boto3.client('s3', region_name='us-east-1')
