class MetadataFormatType:
    def __init__(self, prefix, schema, namespace):
        self.prefix = prefix
        self.schema = schema
        self.namespace = namespace

    def __eq__(self, other):
        if isinstance(other, MetadataFormatType):
            return self.prefix == other.prefix
        return False

    def __repr__(self):
        return f"MetadataFormatType(prefix={self.prefix}, schema={self.schema}, namespace={self.namespace})"


class ListMetadataFormatsType:
    def __init__(self):
        self.formats = []

    def add_format(self, format_type):
        if not isinstance(format_type, MetadataFormatType):
            raise ValueError("format_type must be an instance of MetadataFormatType")

        if any(existing_format.prefix == format_type.prefix for existing_format in self.formats):
            print(f"Format with prefix '{format_type.prefix}' already exists. Skipping addition.")
            return

        self.formats.append(format_type)

    def get_formats(self):
        return self.formats

    def find_format(self, prefix):
        if not prefix:
            return None
        for format_type in self.formats:
            if format_type.prefix == prefix:
                return format_type
        return None


# Unit tests
import unittest

class TestListMetadataFormatsType(unittest.TestCase):
    def setUp(self):
        self.list_metadata_formats = ListMetadataFormatsType()

    def test_get_formats_empty(self):
        self.assertEqual(self.list_metadata_formats.get_formats(), [])

    def test_add_format(self):
        format1 = MetadataFormatType("oai_dc", "http://www.openarchives.org/OAI/2.0/oai_dc.xsd", "http://www.openarchives.org/OAI/2.0/oai_dc/")
        self.list_metadata_formats.add_format(format1)
        self.assertEqual(self.list_metadata_formats.get_formats(), [format1])

    def test_add_invalid_format(self):
        with self.assertRaises(ValueError):
            self.list_metadata_formats.add_format("invalid_format")

    def test_add_duplicate_format(self):
        format1 = MetadataFormatType("oai_dc", "http://www.openarchives.org/OAI/2.0/oai_dc.xsd", "http://www.openarchives.org/OAI/2.0/oai_dc/")
        self.list_metadata_formats.add_format(format1)
        format2 = MetadataFormatType("oai_dc", "http://www.openarchives.org/OAI/2.0/oai_dc.xsd", "http://www.openarchives.org/OAI/2.0/oai_dc/")
        self.list_metadata_formats.add_format(format2)
        self.assertEqual(self.list_metadata_formats.get_formats(), [format1])

    def test_find_format(self):
        format1 = MetadataFormatType("oai_dc", "http://www.openarchives.org/OAI/2.0/oai_dc.xsd", "http://www.openarchives.org/OAI/2.0/oai_dc/")
        self.list_metadata_formats.add_format(format1)
