import uuid

class Message:
    def __init__(self, transaction_id):
        self.transaction_id = transaction_id

    @property
    def transaction_id(self):
        return self._transaction_id

    @transaction_id.setter
    def transaction_id(self, value):
        if not isinstance(value, str) or not self._is_valid_uuid(value):
            raise ValueError("Invalid transaction ID. It must be a valid UUID string.")
        self._transaction_id = value

    @staticmethod
    def _is_valid_uuid(value):
        try:
            uuid.UUID(value)
            return True
        except ValueError:
            return False

    def is_consistent(self):
        raise NotImplementedError("Subclasses should implement this method.")

class Transaction(Message):
    def __init__(self, sender, receiver, amount, currency):
        super().__init__(str(uuid.uuid4()))
        self.sender = sender
        self.receiver = receiver
        self.amount = amount
        self.currency = currency

    @property
    def sender(self):
        return self._sender

    @sender.setter
    def sender(self, value):
        if not isinstance(value, str):
            raise ValueError("Sender must be a string.")
        self._sender = value

    @property
    def receiver(self):
        return self._receiver

    @receiver.setter
    def receiver(self, value):
        if not isinstance(value, str):
            raise ValueError("Receiver must be a string.")
        self._receiver = value

    @property
    def amount(self):
        return self._amount

    @amount.setter
    def amount(self, value):
        if not isinstance(value, (int, float)) or value < 0:
            raise ValueError("Amount must be a non-negative number.")
        self._amount = value

    @property
    def currency(self):
        return self._currency

    @currency.setter
    def currency(self, value):
        if not isinstance(value, str):
            raise ValueError("Currency must be a string.")
        self._currency = value

    def is_consistent(self):
        return self._is_valid_uuid(self.transaction_id) and self.amount >= 0

class Confirmation(Message):
    def __init__(self, transaction_id, success):
        super().__init__(transaction_id)
        self.success = success

    @property
    def success(self):
        return self._success

    @success.setter
    def success(self, value):
        if not isinstance(value, bool):
            raise ValueError("Success must be a boolean.")
        self._success = value

    def is_consistent(self):
        # Assuming we have a way to check if the transaction ID exists
        # For simplicity, let's assume all transaction IDs are valid
        return self._is_valid_uuid(self.transaction_id)

# Example usage:
try:
    transaction = Transaction(sender="Alice", receiver="Bob", amount=100, currency="USD")
    print(f"Transaction ID: {transaction.transaction_id}")
    print(f"Is transaction consistent? {transaction.is_consistent()}")

    confirmation = Confirmation(transaction_id=transaction.transaction_id, success=True)
    print(f"Confirmation for Transaction ID: {confirmation.transaction_id}")
    print(f"Is confirmation consistent? {confirmation.is_consistent()}")
