from email.mime.text import MIMEText
from email.mime.multipart import MIMEMultipart
from urllib.parse import urlencode

class WebMonitoringUtils:

    @staticmethod
    def get_page(url):
        try:
            response = requests.get(url, verify=False)
            response.raise_for_status()
            return response.text
        except requests.exceptions.SSLError as e:
            raise Exception("SSL certificate verification failed.") from e
        except requests.exceptions.RequestException as e:
            raise Exception(f"Error fetching the URL: {url}") from e

    @staticmethod
    def epoch_to_datetime(seconds):
        try:
            return datetime.fromtimestamp(seconds, tz=timezone.utc)
        except (OSError, OverflowError, ValueError) as e:
            raise ValueError("Invalid epoch timestamp.") from e

    @staticmethod
    def datetime_to_epoch(timestamp):
        if timestamp.tzinfo is None or timestamp.tzinfo.utcoffset(timestamp) is None:
            raise ValueError("The datetime object must be timezone-aware.")
        utc_timestamp = timestamp.astimezone(timezone.utc)
        return int(utc_timestamp.timestamp())

    @staticmethod
    def get_UTC_now():
        return datetime.now(timezone.utc)

    @staticmethod
    def build_URL(baseURL, params):
        try:
            return baseURL.format(**params)
        except KeyError as e:
            raise ValueError("Missing parameter for URL construction.") from e

    @staticmethod
    def send_email(subject, message, recipients, email_config):
        try:
            msg = MIMEMultipart()
            msg['From'] = email_config['from_email']
            msg['To'] = ', '.join(recipients)
            msg['Subject'] = subject
            msg.attach(MIMEText(message, 'plain'))

            with smtplib.SMTP(email_config['smtp_server'], email_config['smtp_port']) as server:
