Here's a Python program that simulates a simple load balancing scenario using a class `LoadBalancer`. The program includes methods to initialize the load balancer, add loads to servers, and calculate the minimum number of moves required to balance the servers. The `main()` function handles user input and controls the flow of the program.

```python
class LoadBalancer:
    def __init__(self, n: int):
        self.n = n
        self.loads = []

    def add_load(self):
        self.loads = list(map(int, input(f"Enter the load for each of the {self.n} servers: ").split()))
        if len(self.loads) != self.n:
            raise ValueError("The number of loads provided does not match the number of servers.")

    def calculate_balance_moves(self) -> int:
        total_load = sum(self.loads)

        # Check if total load can be evenly distributed
        if total_load % self.n != 0:
            return -1

        average_load = total_load // self.n
        excess_load = 0
        moves = 0

        for load in self.loads:
            if load > average_load:
                excess_load += load - average_load
            elif load < average_load:
                moves += average_load - load

        # If excess load is not equal to the required moves, balancing is not possible
        if excess_load != moves:
            return -1

        return moves

def main():
    while True:
        n = int(input("Enter the number of servers (or -1 to exit): "))
        if n == -1:
            break

        if n <= 0:
            print("Number of servers must be a positive integer.")
            continue

        load_balancer = LoadBalancer(n)
        load_balancer.add_load()
        result = load_balancer.calculate_balance_moves()

        if result == -1:
            print("It is not possible to balance the servers.")
        else:
            print(f"Minimum number of moves required to balance the servers: {result}")

if __name__ == "__main__":
    main()
```

