Below is a Python Flask application structured using blueprints to manage user authentication and user information retrieval. The application includes placeholder functions for each endpoint, simulating the intended behavior. Passwords are hashed using `werkzeug.security` for security. Additionally, basic input validation is implemented, and appropriate HTTP status codes are returned.

```python
from flask import Flask, Blueprint, request, jsonify
from werkzeug.security import generate_password_hash, check_password_hash

app = Flask(__name__)

# Blueprint for authentication
auth_bp = Blueprint('auth', __name__)

# Blueprint for user management
user_bp = Blueprint('user', __name__)

# In-memory storage for users and tokens
users = {}
tokens = {}

# Helper function to validate email
def is_valid_email(email):
    return "@" in email and "." in email

# Helper function to validate username
def is_valid_username(username):
    return len(username) > 0

# Helper function to validate password
def is_valid_password(password):
    return len(password) >= 6

# Authentication Blueprint
@auth_bp.route('/register', methods=['POST'])
def register():
    data = request.json
    username = data.get('username')
    email = data.get('email')
    password = data.get('password')

    if not (username and email and password):
        return jsonify({'message': 'Missing fields'}), 400
    if not (is_valid_username(username) and is_valid_email(email) and is_valid_password(password)):
        return jsonify({'message': 'Invalid input'}), 400
    if email in users:
        return jsonify({'message': 'Email already registered'}), 400

    hashed_password = generate_password_hash(password)
    users[email] = {'username': username, 'password': hashed_password}
    return jsonify({'message': 'User registered successfully'}), 201

@auth_bp.route('/login', methods=['POST'])
def login():
    data = request.json
    email = data.get('email')
    password = data.get('password')

    if not (email and password):
        return jsonify({'message': 'Missing fields'}), 400
    if email not in users or not check_password_hash(users[email]['password'], password):
        return jsonify({'message': 'Invalid credentials'}), 401

    token = f"token_{email}"
    tokens[token] = email
    return jsonify({'token': token}), 200

@auth_bp.route('/logout', methods=['POST'])
def logout():
    token = request.headers.get('Authorization')
    if token in tokens:
        del tokens[token]
        return jsonify({'message': 'Logged out successfully'}), 200
    return jsonify({'message': 'Invalid token'}), 400

@auth_bp.route('/refresh', methods=['POST'])
def refresh():
    token = request.headers.get('Authorization')
    if token in tokens:
        new_token = f"token_{tokens[token]}"
        tokens[new_token] = tokens.pop(token)
        return jsonify({'token': new_token}), 200
    return jsonify({'message': 'Invalid token'}), 400

# User Blueprint
@user_bp.route('/all', methods=['GET'])
def get_all_users():
    user_list = [{'email': email, 'username': user['username']} for email, user in users.items()]
    return jsonify(user_list), 200

@user_bp.route('/<user_id>', methods=['GET'])
def get_user(user_id):
    for email, user in users.items():
        if user['username'] == user_id:
            return jsonify({'email': email, 'username': user['username']}), 200
    return jsonify({'message': 'User not found'}), 404

@user_bp.route('/update-password', methods=['POST'])
def update_password():
    token = request.headers.get('Authorization')
    if token not in tokens:
        return jsonify({'message': 'Invalid token'}), 400

    data = request.json
    email = tokens[token]
    new_password = data.get('new_password')

    if not new_password or not is_valid_password(new_password):
        return jsonify({'message': 'Invalid password'}), 400

    users[email]['password'] = generate_password_hash(new_password)
    return jsonify({'message': 'Password updated successfully'}), 200

# Register blueprints
app.register_blueprint(auth_bp, url_prefix='/auth')
app.register_blueprint(user_bp, url_prefix='/user')

if __name__ == '__main__':
    app.run(debug=True)
```

