import unittest
import json
from app import app

class UserManagementTestCase(unittest.TestCase):

    def setUp(self):
        self.app = app.test_client()
        self.app.testing = True

    def test_register(self):
        response = self.app.post('/auth/register', json={
            'username': 'testuser',
            'email': 'test@example.com',
            'password': 'password123'
        })
        self.assertEqual(response.status_code, 201)
        self.assertIn(b'User registered successfully', response.data)

    def test_login(self):
        self.app.post('/auth/register', json={
            'username': 'testuser',
            'email': 'test@example.com',
            'password': 'password123'
        })
        response = self.app.post('/auth/login', json={
            'email': 'test@example.com',
            'password': 'password123'
        })
        self.assertEqual(response.status_code, 200)
        self.assertIn(b'token', response.data)

    def test_logout(self):
        self.app.post('/auth/register', json={
            'username': 'testuser',
            'email': 'test@example.com',
            'password': 'password123'
        })
        login_response = self.app.post('/auth/login', json={
            'email': 'test@example.com',
            'password': 'password123'
        })
        token = json.loads(login_response.data.decode())['token']
        response = self.app.post('/auth/logout', headers={'Authorization': token})
        self.assertEqual(response.status_code, 200)
        self.assertIn(b'Logged out successfully', response.data)

    def test_get_all_users(self):
        self.app.post('/auth/register', json={
            'username': 'testuser1',
            'email': 'test1@example.com',
            'password': 'password123'
        })
        self.app.post('/auth/register', json={
            'username': 'testuser2',
            'email': 'test2@example.com',
            'password': 'password123'
        })
        response = self.app.get('/user/all')
        self.assertEqual(response.status_code, 200)
        self.assertEqual(len(json.loads(response.data)), 2)

    def test_update_password(self):
        self.app.post('/auth/register', json={
            'username': 'testuser',
            'email': 'test@example.com',
            'password': 'password123'
        })
        login_response = self.app.post('/auth/login', json={
            'email': 'test@example.com',
            'password': 'password123'
        })
        token = json.loads(login_response.data.decode())['token']
        response = self.app.post('/user/update-password', headers={'Authorization': token}, json={
            'new_password': 'newpassword123'
        })
        self.assertEqual(response.status_code, 200)
        self.assertIn(b'Password updated successfully', response.data)

if __name__ == '__main__':
    unittest.main()
```

