from typing import List, Tuple

def find_amicable_pairs(n: int) -> List[Tuple[int, int]]:
    if not isinstance(n, int):
        raise ValueError("Input must be an integer.")
    if n < 1:
        raise ValueError("Input must be greater than or equal to 1.")

    def sum_of_proper_divisors(x: int) -> int:
        if x < 2:
            return 0
        total = 1
        sqrt_x = int(x**0.5)
        for i in range(2, sqrt_x + 1):
            if x % i == 0:
                total += i
                if i != x // i:
                    total += x // i
        return total

    amicable_pairs = []
    divisor_sums = {}

    for i in range(2, n + 1):
        if i not in divisor_sums:
            divisor_sums[i] = sum_of_proper_divisors(i)

        sum_i = divisor_sums[i]
        if sum_i > i and sum_i <= n:
            if sum_i not in divisor_sums:
                divisor_sums[sum_i] = sum_of_proper_divisors(sum_i)

            sum_sum_i = divisor_sums[sum_i]
            if sum_sum_i == i:
                amicable_pairs.append((i, sum_i))

    return amicable_pairs

