```python
import json
import math
from typing import List, Dict, Tuple

class Lane:
    def __init__(self, lane_id: int, name: str, width: float, points: List[Tuple[float, float]], distance_points: List[float], intercept: float):
        self.lane_id = lane_id
        self.name = name
        self.width = width
        self.points = points
        self.distance_points = distance_points
        self.intercept = intercept

    def __str__(self):
        return f"Lane(ID: {self.lane_id}, Name: {self.name}, Width: {self.width}, Points: {self.points}, Distance Points: {self.distance_points}, Intercept: {self.intercept})"

class Road:
    def __init__(self, road_id: int, name: str, road_type: str, start_pos: Tuple[float, float], length: float, bearing: float, connections: List[int], lanes: List[Lane]):
        self.road_id = road_id
        self.name = name
        self.road_type = road_type
        self.start_pos = start_pos
        self.length = length
        self.bearing = bearing
        self.connections = connections
        self.lanes = lanes

    def calculate_end_point(self) -> Tuple[float, float]:
        rad_bearing = self.degrees_to_radians(self.bearing)
        end_x = self.start_pos[0] + self.length * math.cos(rad_bearing)
        end_y = self.start_pos[1] + self.length * math.sin(rad_bearing)
        return (end_x, end_y)

    @staticmethod
    def degrees_to_radians(degrees: float) -> float:
        return degrees * (math.pi / 180)

    def __str__(self):
        end_pos = self.calculate_end_point()
        return (f"Road(ID: {self.road_id}, Name: {self.name}, Type: {self.road_type}, "
                f"Start: {self.start_pos}, End: {end_pos}, Length: {self.length}, "
                f"Bearing: {self.bearing}, Connections: {self.connections}, Lanes: {[str(lane) for lane in self.lanes]}")

class Map:
    def __init__(self, map_id: int, name: str, version: str, roads: List[Road]):
        self.map_id = map_id
        self.name = name
        self.version = version
        self.roads = roads

    def __str__(self):
        return (f"Map(ID: {self.map_id}, Name: {self.name}, Version: {self.version}, Roads: {[str(road) for road in self.roads]})")

