```python
from pymongo import MongoClient
from datetime import datetime
import re

# MongoDB connection setup
client = MongoClient('mongodb://localhost:27017/')
db = client['employee_db']
attendance_collection = db['attendance']
emp_collection = db['emp']

def validate_date(date_text):
    try:
        datetime.strptime(date_text, '%Y-%m-%d')
        return True
    except ValueError:
        return False

def validate_employee_id(emp_id):
    return isinstance(emp_id, int) and emp_id > 0

def insert_attendance_record(emp_id, name, date, time):
    if not validate_employee_id(emp_id):
        return "Invalid employee ID."
    if not validate_date(date):
        return "Invalid date format. Use YYYY-MM-DD."
    if not re.match(r'^\d{2}:\d{2}:\d{2}$', time):
        return "Invalid time format. Use HH:MM:SS."

    record = {
        'emp_id': emp_id,
        'name': name,
        'date': date,
        'time': time
    }

    try:
        attendance_collection.insert_one(record)
        return "Attendance record inserted successfully."
    except Exception as e:
        return f"Error inserting record: {str(e)}"

def fetch_all_attendance_records():
    try:
        records = attendance_collection.find()
        return list(records)
    except Exception as e:
        return f"Error fetching records: {str(e)}"

def fetch_attendance_by_date(date):
    if not validate_date(date):
        return "Invalid date format. Use YYYY-MM-DD."

    try:
        records = attendance_collection.find({'date': date})
        return list(records)
    except Exception as e:
        return f"Error fetching records: {str(e)}"

def fetch_attendance_by_employee_id(emp_id):
    if not validate_employee_id(emp_id):
        return "Invalid employee ID."

    try:
        records = attendance_collection.find({'emp_id': emp_id})
        return list(records)
    except Exception as e:
        return f"Error fetching records: {str(e)}"

def fetch_attendance_by_employee_id_and_date(emp_id, date):
    if not validate_employee_id(emp_id):
        return "Invalid employee ID."
    if not validate_date(date):
        return "Invalid date format. Use YYYY-MM-DD."

    try:
        records = attendance_collection.find({'emp_id': emp_id, 'date': date})
        return list(records)
    except Exception as e:
        return f"Error fetching records: {str(e)}"

def get_employee_contact(emp_id):
    if not validate_employee_id(emp_id):
        return "Invalid employee ID."

    try:
        emp_record = emp_collection.find_one({'emp_id': emp_id}, {'_id': 0, 'contact': 1})
        if emp_record:
            return emp_record.get('contact', "Contact information not available.")
        else:
            return "Employee not found."
    except Exception as e:
        return f"Error fetching contact: {str(e)}"

# Test cases
def test_program():
    print(insert_attendance_record(1, "John Doe", "2023-10-01", "09:00:00"))
    print(fetch_all_attendance_records())
    print(fetch_attendance_by_date("2023-10-01"))
    print(fetch_attendance_by_employee_id(1))
    print(fetch_attendance_by_employee_id_and_date(1, "2023-10-01"))
    print(get_employee_contact(1))

if __name__ == "__main__":
    test_program()
```

