```python
def caesar_cipher_encrypt(text, shift):
    if not text.isalpha():
        raise ValueError("Input text must contain only alphabetic characters.")

    encrypted_text = []
    for char in text:
        if char.isupper():
            encrypted_text.append(chr((ord(char) - 65 + shift) % 26 + 65))
        else:
            encrypted_text.append(chr((ord(char) - 97 + shift) % 26 + 97))

    return ''.join(encrypted_text)

def binary_encode(text):
    return ' '.join(format(ord(char), '08b') for char in text)

def binary_decode(binary_string):
    binary_values = binary_string.split()
    text = ''.join(chr(int(bv, 2)) for bv in binary_values)
    return text

def encrypt(text, shift):
    if len(text) > 4096:
        raise ValueError("Input text exceeds the maximum allowed length of 4096 characters.")

    encrypted_text = caesar_cipher_encrypt(text, shift)
    return binary_encode(encrypted_text)

def decrypt(binary_string):
    try:
        encrypted_text = binary_decode(binary_string)
    except ValueError:
        raise ValueError("Invalid binary string format.")

    # Assuming the shift is known or can be determined
    # For demonstration, let's assume a shift of 1 for decryption
    shift = 1
    decrypted_text = caesar_cipher_encrypt(encrypted_text, -shift)
    return decrypted_text

# Unit tests
def test_caesar_cipher_encrypt():
    assert caesar_cipher_encrypt("ABC", 1) == "BCD"
    assert caesar_cipher_encrypt("xyz", 3) == "abc"
    assert caesar_cipher_encrypt("HelloWorld", 5) == "MjqqtBtwqi"
    try:
        caesar_cipher_encrypt("Hello123", 5)
    except ValueError as e:
        assert str(e) == "Input text must contain only alphabetic characters."

def test_binary_encode_decode():
    text = "Hello"
    binary = binary_encode(text)
    assert binary == "01001000 01100101 01101100 01101100 01101111"
    assert binary_decode(binary) == text

def test_encrypt_decrypt():
    text = "HelloWorld"
    shift = 3
    encrypted = encrypt(text, shift)
    decrypted = decrypt(encrypted)
    assert decrypted == caesar_cipher_encrypt(text, -shift)

def run_tests():
    test_caesar_cipher_encrypt()
    test_binary_encode_decode()
    test_encrypt_decrypt()
    print("All tests passed.")

if __name__ == "__main__":
    run_tests()
```

### Explanation:

1. **Caesar Cipher Encryption**: The `caesar_cipher_encrypt` function shifts each letter in the input text by a specified number of places. It raises an error if the input contains non-alphabetic characters.

