import torch
import torch.nn as nn

class PyTorchModelInterface:
    def __init__(self, model=None, model_path=None, transformer=None, device='cpu'):
        self.device = torch.device(device)
        self.transformer = transformer
        self.model = model.to(self.device) if model is not None else None

        if self.model is None and model_path is not None:
            self.load_model(model_path)

    def load_model(self, model_path):
        try:
            self.model = torch.load(model_path, map_location=self.device)
            self.model.to(self.device)
        except FileNotFoundError:
            raise FileNotFoundError(f"Model file not found at path: {model_path}")
        except Exception as e:
            raise RuntimeError(f"An error occurred while loading the model: {e}")

    def predict(self, input_tensor, transform_data=False):
        if not isinstance(input_tensor, torch.Tensor):
            raise TypeError("Input must be a PyTorch tensor.")

        if transform_data and self.transformer is not None:
            try:
                input_tensor = self.transformer.transform(input_tensor)
            except Exception as e:
                raise RuntimeError(f"An error occurred during transformation: {e}")

        if self.model is None:
            raise RuntimeError("Model is not loaded. Please load a model before making predictions.")

        self.set_eval_mode()

        try:
            input_tensor = input_tensor.to(self.device)
            with torch.no_grad():
                output = self.model(input_tensor)
            return output
        except Exception as e:
            raise RuntimeError(f"An error occurred during prediction: {e}")

    def set_eval_mode(self):
        if self.model is None:
            raise RuntimeError("Model is not loaded. Please load a model before setting evaluation mode.")
        self.model.eval()

    def get_num_output_nodes(self, inp_size):
        if self.model is None:
            raise RuntimeError("Model is not loaded. Please load a model to get the number of output nodes.")

        try:
            # Create a dummy input tensor with the specified input size
            dummy_input = torch.randn(1, *inp_size).to(self.device)
            with torch.no_grad():
                output = self.model(dummy_input)
            return output.size(1)  # Assuming the output is of shape (batch_size, num_classes)
        except Exception as e:
            raise RuntimeError(f"An error occurred while determining the number of output nodes: {e}")

