    if chamber not in valid_chambers:
        raise TypeError(f"Invalid chamber: {chamber}. Must be one of {valid_chambers}.")
    return chamber

def get_congress(year):
    if year < 1789:
        raise CongressError("Year must be 1789 or later.")
    return (year - 1789) // 2 + 1

def parse_date(date_input):
    if isinstance(date_input, (datetime.datetime, datetime.date)):
        return date_input
    try:
        return dateutil_parser.parse(date_input)
    except ImportError:
        # Fallback to strptime if dateutil is not available
        for fmt in ("%Y-%m-%d", "%Y/%m/%d", "%d-%m-%Y", "%d/%m/%Y"):
            try:
                return datetime.datetime.strptime(date_input, fmt)
            except ValueError:
                continue
        raise ValueError("Date format not recognized.")

def u(text):
    if isinstance(text, bytes):
        text = text.decode('utf-8', 'replace')
    if isinstance(text, str):
        text = text.replace('\r\n', '\n')
    return text

def get_offset(page):
    if page < 1:
        raise CongressError("Page number must be 1 or greater.")
    return (page - 1) * 20

CURRENT_CONGRESS = get_congress(datetime.datetime.now().year)

# Test cases
def test_congress_utils():
    # Test check_chamber
    assert check_chamber('house') == 'house'
    assert check_chamber('senate') == 'senate'
    assert check_chamber('both') == 'both'
    try:
        check_chamber('invalid')
    except TypeError as e:
        assert str(e) == "Invalid chamber: invalid. Must be one of {'house', 'senate', 'both'}."

    # Test get_congress
    assert get_congress(1789) == 1
    assert get_congress(1791) == 2
    assert get_congress(2023) == 97
    try:
        get_congress(1788)
    except CongressError as e:
        assert str(e) == "Year must be 1789 or later."

    # Test parse_date
    assert parse_date("2023-10-05") == datetime.datetime(2023, 10, 5)
    assert parse_date("10/05/2023") == datetime.datetime(2023, 10, 5)
    assert parse_date(datetime.date(2023, 10, 5)) == datetime.date(2023, 10, 5)
    assert parse_date(datetime.datetime(2023, 10, 5)) == datetime.datetime(2023, 10, 5)

    # Test u
    assert u("Hello\nWorld") == "Hello\nWorld"
    assert u(b"Hello\r\nWorld") == "Hello\nWorld"

    # Test get_offset
    assert get_offset(1) == 0
    assert get_offset(2) == 20
    try:
        get_offset(0)
    except CongressError as e:
        assert str(e) == "Page number must be 1 or greater."

    # Test CURRENT_CONGRESS
    current_year = datetime.datetime.now().year
    expected_congress = get_congress(current_year)
    assert CURRENT_CONGRESS == expected_congress

    print("All tests passed.")

if __name__ == "__main__":
    test_congress_utils()
