        print(f"The title of the book is {self._title}")

    @property
    def title(self):
        return self._title


class Author(Person):
    def __init__(self, firstname, lastname, oeuvre):
        super().__init__(firstname, lastname)
        self._oeuvre = oeuvre

    def list_works(self):
