            raise UnsupportedKeyTypeException("Key must be a tuple of GrammarToken objects.")

    def _validate_value(self, value):
        if not isinstance(value, (set, list, GrammarToken)):
            raise UnsupportedKeyTypeException("Value must be a set, list, or a single GrammarToken.")
        if isinstance(value, list) or isinstance(value, set):
            if not all(isinstance(token, GrammarToken) for token in value):
                raise UnsupportedKeyTypeException("All elements in the value must be GrammarToken objects.")
        elif isinstance(value, GrammarToken):
            value = {value}

        return value

    def add(self, key, tokens):
        self._validate_key(key)
        tokens = self._validate_value(tokens)
        if key not in self._sets:
            self._sets[key] = set()
        self._sets[key].update(tokens)
        self.dirty = True

    def add_empty(self, key):
        self._validate_key(key)
        if key not in self._sets:
            self._sets[key] = set()
            self.dirty = True

    def remove(self, key, tokens):
        self._validate_key(key)
        tokens = self._validate_value(tokens)
        if key in self._sets:
            self._sets[key].difference_update(tokens)
            if not self._sets[key]:
                del self._sets[key]
            self.dirty = True

    def get(self, key):
        self._validate_key(key)
        return self._sets.get(key, set())

    def reset(self):
        self._sets.clear()
