class Test:
    def __init__(self, name):
        self._name = name

    def name(self):
        return self._name

    @classmethod
    def description(cls):
        return getattr(cls, '_description', None)

class TestRegistry:
    def __init__(self):
        self._registry = {}

    def register(self, test_class):
        if not issubclass(test_class, Test):
            raise ValueError("Class must inherit from Test")

        class_name = test_class.name()
        if class_name in self._registry:
            raise ValueError(f"Class with name '{class_name}' is already registered")

        self._registry[class_name] = test_class

    def get(self, class_name):
        if class_name not in self._registry:
            raise ValueError(f"Class with name '{class_name}' is not registered")
        return self._registry[class_name]

    def list_registered(self):
        return list(self._registry.keys())

# Test cases
def test_test_registry():
    registry = TestRegistry()

