To design the `MockTestRunner` class, we need to simulate the execution of various types of layout tests. The class will manage different test types, such as text comparison, pixel tests, and audio tests, as well as handle virtual tests and reference tests. Here's a possible implementation:

```python
class MockTestRunner:
    def __init__(self):
        self.tests = []
        self.results = {
            'passed': [],
            'failed': [],
            'skipped': []
        }

    def add_test(self, name, test_type, expected_result, actual_result=None, skip=False):
        if test_type not in ['text', 'pixel', 'audio', 'virtual', 'reftest']:
            raise ValueError(f"Invalid test type: {test_type}")

        if expected_result is None and test_type != 'virtual':
            raise ValueError("Expected result must be provided for non-virtual tests")

        test = {
            'name': name,
            'type': test_type,
            'expected': expected_result,
            'actual': actual_result,
            'skip': skip
        }
        self.tests.append(test)

    def run_tests(self):
        for test in self.tests:
            if test['skip']:
                self.results['skipped'].append(self._format_result(test, 'skipped'))
                continue

            try:
                if test['type'] == 'virtual':
                    self.results['passed'].append(self._format_result(test, 'passed'))
                else:
                    if self._compare_results(test):
                        self.results['passed'].append(self._format_result(test, 'passed'))
                    else:
                        self.results['failed'].append(self._format_result(test, 'failed'))
            except Exception as e:
                self.results['failed'].append(self._format_result(test, 'failed', error=str(e)))

        return self._summarize_results()

    def _compare_results(self, test):
        if test['type'] == 'text':
            return test['expected'] == test['actual']
        elif test['type'] == 'pixel':
            return test['expected'] == test['actual']
        elif test['type'] == 'audio':
            return test['expected'] == test['actual']
        elif test['type'] == 'reftest':
            # Simulate reftest comparison
            return test['expected'] == test['actual']
        return False

    def _format_result(self, test, status, error=None):
        return {
            'name': test['name'],
            'type': test['type'],
            'expected': test['expected'],
            'actual': test['actual'],
            'status': status,
            'error': error
        }

    def _summarize_results(self):
        summary = {
            'total': len(self.tests),
            'passed': len(self.results['passed']),
            'failed': len(self.results['failed']),
            'skipped': len(self.results['skipped']),
            'details': {
                'passed': self.results['passed'],
                'failed': self.results['failed'],
                'skipped': self.results['skipped']
            }
        }
        return summary

# Example usage:
runner = MockTestRunner()
runner.add_test('test1', 'text', 'expected text', 'expected text')
runner.add_test('test2', 'pixel', 'expected_checksum', 'expected_checksum')
runner.add_test('test3', 'audio', 'expected_audio_data', 'expected_audio_data')
runner.add_test('test4', 'reftest', 'expected_ref', 'expected_ref')
runner.add_test('test5', 'virtual', None)
runner.add_test('test6', 'text', 'expected text', 'actual text', skip=True)

summary = runner.run_tests()
print(summary)
```

### Key Features:
- **Test Addition**: The `add_test` method allows adding tests with expected results. It checks for valid test types and ensures expected results are provided unless the test is virtual.
- **Test Execution**: The `run_tests` method simulates running all tests, comparing expected and actual results, and categorizing them as passed, failed, or skipped.
- **Result Comparison**: The `_compare_results` method handles the logic for comparing expected and actual results based on test type.
- **Result Formatting**: The `_format_result` method structures the result for each test, including any errors encountered.
- **Summary**: The `_summarize_results` method provides a structured summary of the test results, making it easy to filter by status.

This implementation provides a flexible and extensible framework for simulating layout tests in a mock environment.

