```python
from typing import List, Callable, Dict
import time

class VoIPManager:
    def __init__(self):
        self.calls: Dict[int, VoIPController] = {}
        self.call_states: Dict[int, Callable[[CallState], None]] = {}
        self.audio_frame_handlers: Dict[int, Dict[str, Callable]] = {}

    def start_call(self, call_id: int, endpoints: List[Endpoint], encryption_key: bytes, is_outgoing: bool):
        if not isinstance(call_id, int):
            raise ValueError("call_id must be an integer")
        if not isinstance(endpoints, list) or not all(isinstance(ep, Endpoint) for ep in endpoints):
            raise ValueError("endpoints must be a list of Endpoint objects")
        if not isinstance(encryption_key, bytes):
            raise ValueError("encryption_key must be bytes")
        if not isinstance(is_outgoing, bool):
            raise ValueError("is_outgoing must be a boolean")

        if call_id in self.calls:
            raise ValueError(f"Call with call_id {call_id} already exists")

        voip_controller = VoIPController()
        voip_controller.start_call(endpoints, encryption_key, is_outgoing)
        self.calls[call_id] = voip_controller
        self.audio_frame_handlers[call_id] = {'send': None, 'recv': None}
        self._start_call_timer(call_id)

    def end_call(self, call_id: int):
        if call_id not in self.calls:
            raise ValueError(f"No call found with call_id {call_id}")

        self.calls[call_id].end_call()
        self._stop_call_timer(call_id)
        del self.calls[call_id]
        del self.call_states[call_id]
        del self.audio_frame_handlers[call_id]

    def get_call_duration(self, call_id: int) -> float:
        if call_id not in self.calls:
            raise ValueError(f"No call found with call_id {call_id}")

        return self.calls[call_id].get_duration()

    def set_call_state_changed_handler(self, call_id: int, handler: Callable[[CallState], None]):
        if call_id not in self.calls:
            raise ValueError(f"No call found with call_id {call_id}")
        if not callable(handler):
            raise ValueError("handler must be callable")

        self.call_states[call_id] = handler
        self.calls[call_id].set_state_changed_handler(handler)

    def set_call_audio_frame_handlers(self, call_id: int, send_handler: Callable[[int], bytes], recv_handler: Callable[[bytes], None]):
        if call_id not in self.calls:
            raise ValueError(f"No call found with call_id {call_id}")
        if not callable(send_handler) or not callable(recv_handler):
            raise ValueError("send_handler and recv_handler must be callable")

        self.audio_frame_handlers[call_id]['send'] = send_handler
        self.audio_frame_handlers[call_id]['recv'] = recv_handler
        self.calls[call_id].set_audio_frame_handlers(send_handler, recv_handler)

    def _start_call_timer(self, call_id: int):
        self.calls[call_id].start_time = time.time()

    def _stop_call_timer(self, call_id: int):
        if call_id in self.calls:
            self.calls[call_id].end_time = time.time()

