```python
import hashlib
import argparse
import os

class FileDigestComparer:
    def __init__(self, filename):
        self.filename = filename
        self.md5_digest = self.compute_md5()
        self.sha1_digest = self.compute_sha1()

    def compute_md5(self):
        """Computes and returns the MD5 digest of the file."""
        hash_md5 = hashlib.md5()
        try:
            with open(self.filename, "rb") as f:
                for chunk in iter(lambda: f.read(4096), b""):
                    hash_md5.update(chunk)
        except FileNotFoundError:
            raise Exception(f"File {self.filename} not found.")
        return hash_md5.hexdigest()

    def compute_sha1(self):
        """Computes and returns the SHA1 digest of the file."""
        hash_sha1 = hashlib.sha1()
        try:
            with open(self.filename, "rb") as f:
                for chunk in iter(lambda: f.read(4096), b""):
                    hash_sha1.update(chunk)
        except FileNotFoundError:
            raise Exception(f"File {self.filename} not found.")
        return hash_sha1.hexdigest()

    def compare_digests(self, other):
        """Compares the MD5 and SHA1 digests of the current file with another FileDigestComparer instance."""
        if not isinstance(other, FileDigestComparer):
            raise ValueError("The other object must be an instance of FileDigestComparer.")

        md5_identical = self.md5_digest == other.md5_digest
        sha1_identical = self.sha1_digest == other.sha1_digest
        return md5_identical and sha1_identical

    def __str__(self):
        """Returns a string representation of the file's name and its digests."""
        return (f"File: {self.filename}\n"
                f"MD5: {self.md5_digest}\n"
                f"SHA1: {self.sha1_digest}")

def main():
    parser = argparse.ArgumentParser(description="Compute and compare file digests.")
    parser.add_argument('filenames', metavar='FILE', type=str, nargs='+', help='File(s) to process')

    args = parser.parse_args()

    if len(args.filenames) == 1:
        # Single file: print its digests
        try:
            file_comparer = FileDigestComparer(args.filenames[0])
            print(file_comparer)
        except Exception as e:
            print(e)
    elif len(args.filenames) == 2:
        # Two files: compare their digests
        try:
            file_comparer1 = FileDigestComparer(args.filenames[0])
            file_comparer2 = FileDigestComparer(args.filenames[1])

            if file_comparer1.compare_digests(file_comparer2):
                print(f"The files {args.filenames[0]} and {args.filenames[1]} are identical.")
            else:
                print(f"The files {args.filenames[0]} and {args.filenames[1]} are not identical.")
        except Exception as e:
            print(e)
    else:
        parser.print_help()

if __name__ == "__main__":
    main()
