class MysqlManager:
    def __init__(self, endpoint, username, password):
        self.endpoint = endpoint
        self.username = username
        self.password = password
        self.connection = None
        self.cursor = None
        try:
            self.connection = mysql.connector.connect(
                host=self.endpoint,
                user=self.username,
                password=self.password
            )
            self.cursor = self.connection.cursor()
        except mysql.connector.Error as err:
            print(f"Error connecting to MySQL: {err}")
            if self.connection:
                self.connection.close()

    def create_database(self, database_name):
        try:
            self.cursor.execute(f"SHOW DATABASES LIKE '{database_name}'")
            result = self.cursor.fetchone()
            if result:
                print(f"Database '{database_name}' already exists.")
            else:
                self.cursor.execute(f"CREATE DATABASE {database_name}")
                print(f"Database '{database_name}' created successfully.")
        except mysql.connector.Error as err:
            print(f"Error creating database: {err}")

    def use_database(self, database_name):
        try:
            self.cursor.execute(f"USE {database_name}")
        except mysql.connector.Error as err:
            print(f"Error selecting database: {err}")

    def create_table(self, database_name, table_name, table_schema):
        try:
            self.use_database(database_name)
            self.cursor.execute(f"SHOW TABLES LIKE '{table_name}'")
            result = self.cursor.fetchone()
            if result:
                print(f"Table '{table_name}' already exists in database '{database_name}'.")
            else:
                self.cursor.execute(f"CREATE TABLE {table_name} ({table_schema})")
                print(f"Table '{table_name}' created successfully in database '{database_name}'.")
        except mysql.connector.Error as err:
            print(f"Error creating table: {err}")

    def insert(self, insert_command):
        try:
            self.cursor.execute(insert_command)
            print("Record inserted successfully.")
        except mysql.connector.Error as err:
            print(f"Error inserting record: {err}")

    def commit(self):
        try:
            self.connection.commit()
            print("Transaction committed successfully.")
        except mysql.connector.Error as err:
            print(f"Error committing transaction: {err}")

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        if self.cursor:
            self.cursor.close()
        if self.connection:
            self.connection.close()
        print("Database connection closed.")

