```python
from flask import Flask, request, jsonify
import numpy as np
from scipy import stats

app = Flask(__name__)

def validate_samples(samples):
    if not isinstance(samples, list) or not all(isinstance(sample, list) for sample in samples):
        return False, "Samples must be a list of lists."
    if len(samples) == 1 and len(samples[0]) <= 30:
        return False, "One-sample Z-test requires more than 30 unique values."
    if len(samples) == 2 and (len(samples[0]) <= 30 or len(samples[1]) <= 30):
        return False, "Two-sample Z-test requires more than 30 unique values in each sample."
    return True, ""

@app.route('/ztest', methods=['POST'])
def ztest():
    data = request.get_json()
    samples = data.get('samples')
    if not samples:
        return jsonify({"error": "No samples provided."}), 400

    valid, message = validate_samples(samples)
    if not valid:
        return jsonify({"error": message}), 400

    if len(samples) == 1:
        z_stat, p_value = stats.zscore(samples[0]), stats.norm.sf(abs(stats.zscore(samples[0])))
        return jsonify({"z_stat": z_stat.tolist(), "p_value": p_value.tolist()})
    else:
        z_stat, p_value = stats.ttest_ind(samples[0], samples[1], equal_var=True)
        return jsonify({"z_stat": z_stat, "p_value": p_value})

@app.route('/ttest-equalvariance', methods=['POST'])
def ttest_equalvariance():
    data = request.get_json()
    samples = data.get('samples')
    if not samples or len(samples) != 2:
        return jsonify({"error": "Two samples must be provided."}), 400

    t_stat, p_value = stats.ttest_ind(samples[0], samples[1], equal_var=True)
    return jsonify({"t_stat": t_stat, "p_value": p_value})

@app.route('/ttest-unequalvariance', methods=['POST'])
def ttest_unequalvariance():
    data = request.get_json()
    samples = data.get('samples')
    if not samples or len(samples) != 2:
        return jsonify({"error": "Two samples must be provided."}), 400

    t_stat, p_value = stats.ttest_ind(samples[0], samples[1], equal_var=False)
    return jsonify({"t_stat": t_stat, "p_value": p_value})

@app.route('/normaltest', methods=['POST'])
def normaltest():
    data = request.get_json()
    samples = data.get('samples')
    if not samples:
        return jsonify({"error": "No samples provided."}), 400

    for sample in samples:
        k2, p_value = stats.normaltest(sample)
        return jsonify({"k2": k2, "p_value": p_value})

@app.route('/outliertest', methods=['POST'])
def outliertest():
    data = request.get_json()
    samples = data.get('samples')
    if not samples:
        return jsonify({"error": "No samples provided."}), 400

    outliers = []
    for sample in samples:
        z_scores = np.abs(stats.zscore(sample))
        outliers.append(sample[z_scores > 3].tolist())
    return jsonify({"outliers": outliers})

@app.route('/histogram', methods=['POST'])
def histogram():
    data = request.get_json()
    samples = data.get('samples')
    if not samples:
        return jsonify({"error": "No samples provided."}), 400

    histograms = []
    for sample in samples:
        hist, bin_edges = np.histogram(sample, bins='auto')
        histograms.append({"hist": hist.tolist(), "bin_edges": bin_edges.tolist()})
    return jsonify({"histograms": histograms})

@app.route('/zvalue', methods=['POST'])
def zvalue():
    data = request.get_json()
    samples = data.get('samples')
    if not samples:
        return jsonify({"error": "No samples provided."}), 400

    z_scores = [stats.zscore(sample).tolist() for sample in samples]
    return jsonify({"z_scores": z_scores})

@app.route('/max', methods=['POST'])
def max_value():
    data = request.get_json()
    samples = data.get('samples')
    if not samples:
        return jsonify({"error": "No samples provided."}), 400

    max_values = [np.max(sample) for sample in samples]
    return jsonify({"max_values": max_values})

@app.route('/min', methods=['POST'])
