    samples = data.get('samples')
    if not samples:
        return jsonify({"error": "No samples provided."}), 400

    ranges = [np.ptp(sample) for sample in samples]
    return jsonify({"ranges": ranges})

@app.route('/kurtosis', methods=['POST'])
def kurtosis():
    data = request.get_json()
    samples = data.get('samples')
    if not samples:
