```python
# domain_validator.py

import re
from datetime import datetime

class DomainValidator:
    def __init__(self):
        self.domain_regex = re.compile(
            r'^(?:[a-zA-Z0-9-]{1,63}\.){1,127}[a-zA-Z]{2,63}$'
        )
        self.ipv4_regex = re.compile(
            r'^(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$'
        )
        self.months = {
            'jan': 'Jan', 'feb': 'Feb', 'mar': 'Mar', 'apr': 'Apr', 'may': 'May', 'jun': 'Jun',
            'jul': 'Jul', 'aug': 'Aug', 'sep': 'Sep', 'oct': 'Oct', 'nov': 'Nov', 'dec': 'Dec',
            'January': 'Jan', 'February': 'Feb', 'March': 'Mar', 'April': 'Apr', 'May': 'May', 'June': 'Jun',
            'July': 'Jul', 'August': 'Aug', 'September': 'Sep', 'October': 'Oct', 'November': 'Nov', 'December': 'Dec'
        }

    def is_valid_domain(self, domain):
        if not isinstance(domain, str):
            return False
        return bool(self.domain_regex.match(domain))

    def is_valid_ip(self, ip):
        if not isinstance(ip, str):
            return False
        return bool(self.ipv4_regex.match(ip))

    def convert_month(self, month):
        if not isinstance(month, str):
            return None
        return self.months.get(month.lower()[:3], None)

    def pad_number(self, number):
        if not isinstance(number, int) or not (0 <= number <= 99):
            return None
        return f'{number:02}'

    def format_date(self, date_str):
        try:
            for fmt in ("%d-%b-%Y", "%d-%B-%Y", "%Y-%m-%d", "%d/%m/%Y", "%d-%m-%Y"):
                try:
                    date_obj = datetime.strptime(date_str, fmt)
                    return date_obj.strftime("%d-%b-%Y")
                except ValueError:
                    continue
            return None
        except Exception:
            return None

# tests.py

import unittest
from domain_validator import DomainValidator

class TestDomainValidator(unittest.TestCase):
    def setUp(self):
        self.validator = DomainValidator()

    def test_valid_domain(self):
        self.assertTrue(self.validator.is_valid_domain("example.com"))
        self.assertTrue(self.validator.is_valid_domain("sub.example.co.uk"))

    def test_invalid_domain(self):
        self.assertFalse(self.validator.is_valid_domain("example..com"))
        self.assertFalse(self.validator.is_valid_domain("256.256.256.256"))
        self.assertFalse(self.validator.is_valid_domain(12345))

    def test_valid_ip(self):
        self.assertTrue(self.validator.is_valid_ip("192.168.1.1"))
        self.assertTrue(self.validator.is_valid_ip("255.255.255.255"))

    def test_invalid_ip(self):
        self.assertFalse(self.validator.is_valid_ip("256.256.256.256"))
        self.assertFalse(self.validator.is_valid_ip("192.168.1"))
        self.assertFalse(self.validator.is_valid_ip("example.com"))

    def test_convert_month(self):
        self.assertEqual(self.validator.convert_month("January"), "Jan")
        self.assertEqual(self.validator.convert_month("feb"), "Feb")
        self.assertEqual(self.validator.convert_month("DEC"), "Dec")
        self.assertIsNone(self.validator.convert_month("invalid"))

    def test_pad_number(self):
        self.assertEqual(self.validator.pad_number(5), "05")
        self.assertEqual(self.validator.pad_number(10), "10")
        self.assertIsNone(self.validator.pad_number(100))
        self.assertIsNone(self.validator.pad_number("10"))

    def test_format_date(self):
        self.assertEqual(self.validator.format_date("01-Jan-2023"), "01-Jan-2023")
        self.assertEqual(self.validator.format_date("01 January 2023"), "01-Jan-2023")
        self.assertEqual(self.validator.format_date("2023-01-01"), "01-Jan-2023")
        self.assertEqual(self.validator.format_date("01/01/2023"), "01-Jan-2023")
        self.assertEqual(self.validator.format_date("01-01-2023"), "01-Jan-2023")
        self.assertIsNone(self.validator.format_date("invalid-date"))

if __name__ == '__main__':
    unittest.main()
