```python
import os
import time

class DirectoryTraversal:
    def __init__(self, root_dir):
        self.root_dir = root_dir
        self.start_time = None
        self.end_time = None

    def validate_root_directory(self):
        if not os.path.exists(self.root_dir):
            raise ValueError(f"The specified root directory '{self.root_dir}' does not exist.")
        if not os.path.isdir(self.root_dir):
            raise ValueError(f"The specified path '{self.root_dir}' is not a directory.")
        if not os.access(self.root_dir, os.R_OK):
            raise PermissionError(f"Permission denied: Cannot read the directory '{self.root_dir}'.")

    def traverse_directory(self):
        self.validate_root_directory()
        self.start_time = time.time()
        try:
            self._process_directory(self.root_dir)
        except Exception as e:
            print(f"Error during traversal: {e}")
        self.end_time = time.time()
        self.print_total_time()

    def _process_directory(self, current_dir):
        try:
            with os.scandir(current_dir) as it:
                for entry in it:
                    if entry.is_file(follow_symlinks=False):
                        try:
                            print(os.path.abspath(entry.path))
                        except PermissionError:
                            print(f"Permission denied: Cannot access file '{entry.path}'")
                    elif entry.is_dir(follow_symlinks=False):
                        try:
                            self._process_directory(entry.path)
                        except PermissionError:
                            print(f"Permission denied: Cannot access directory '{entry.path}'")
        except PermissionError:
            print(f"Permission denied: Cannot access directory '{current_dir}'")
        except OSError as e:
            print(f"Error accessing '{current_dir}': {e}")

    def print_total_time(self):
        if self.start_time is not None and self.end_time is not None:
            total_time = self.end_time - self.start_time
            print(f"Total time taken for traversal: {total_time:.2f} seconds")

if __name__ == "__main__":
    import sys

    if len(sys.argv) != 2:
        print("Usage: python script.py <root_directory>")
        sys.exit(1)

    root_directory = sys.argv[1]
    traversal = DirectoryTraversal(root_directory)
    traversal.traverse_directory()
```

### Explanation:

1. **Initialization**: The `DirectoryTraversal` class is initialized with a `root_dir` which is the starting point for the directory traversal.

2. **Validation**: The `validate_root_directory` method checks if the root directory exists, is a directory, and is readable.

3. **Traversal**: The `traverse_directory` method starts the traversal, records the start time, and handles any exceptions that occur during the traversal.

4. **Recursive Processing**: The `_process_directory` method recursively processes each directory and file. It handles permission errors and other OS errors gracefully, printing appropriate messages.

5. **Timing**: The total time taken for the traversal is calculated and printed using `print_total_time`.

6. **Execution**: The script expects a command-line argument for the root directory and performs the traversal if the argument is valid.

This program ensures that only accessible files and directories are processed, and it continues the traversal even if some files or directories cannot be accessed due to permission issues.

