class Audit:
    def __init__(self, audit_id):
        self.audit_id = audit_id
        self.archived = False
        self.assessments = []

    def add_assessment(self, assessment):
        self.assessments.append(assessment)


class Assessment:
    def __init__(self, assessment_id):
        self.assessment_id = assessment_id
        self.archived = False
        self.evidence = []

    def add_evidence(self, evidence):
        self.evidence.append(evidence)


class Evidence:
    def __init__(self, evidence_id):
        self.evidence_id = evidence_id
        self.archived = False


class ArchivingSystem:
    def __init__(self):
        self.audits = {}

    def add_audit(self, audit):
        self.audits[audit.audit_id] = audit

    def archive_audit(self, audit_id):
        if audit_id not in self.audits:
            return f"Error: Audit with ID {audit_id} does not exist."

        audit = self.audits[audit_id]

        # Start archiving process
        try:
            audit.archived = True
            for assessment in audit.assessments:
                assessment.archived = True
                for evidence in assessment.evidence:
                    evidence.archived = True
        except Exception as e:
            # Rollback in case of failure
            audit.archived = False
            for assessment in audit.assessments:
                assessment.archived = False
                for evidence in assessment.evidence:
                    evidence.archived = False
            return f"Error: Failed to archive due to {str(e)}."

        return f"Audit {audit_id} and all related items archived successfully."

    def query_archived_items(self, item_type):
        if item_type not in ['Audit', 'Assessment', 'Evidence']:
            return "Error: Invalid item type. Please choose from 'Audit', 'Assessment', or 'Evidence'."

        archived_ids = []

