        elif item_type == 'Assessment':
            for audit in self.audits.values():
                for assessment in audit.assessments:
                    if assessment.archived:
                        archived_ids.append(assessment.assessment_id)

        elif item_type == 'Evidence':
            for audit in self.audits.values():
                for assessment in audit.assessments:
                    for evidence in assessment.evidence:
                        if evidence.archived:
                            archived_ids.append(evidence.evidence_id)

        return archived_ids


# Test cases
