To create a Python program that integrates with a configuration management system like Puppet to verify the integrity of installed packages, we can use a plugin system. This system will allow us to load a YAML file containing the state of files as managed by Puppet, including their checksums, and verify the integrity of each package by comparing the actual file checksums with those specified by Puppet.

Here's a step-by-step implementation:

### Step 1: Define the Plugin System

We'll define a simple plugin system with hooks for configuration and verification.

```python
import yaml
import hashlib
import os

class PluginSystem:
    def __init__(self):
        self.config = {}
        self.plugins = []

    def register_plugin(self, plugin):
        self.plugins.append(plugin)

    def config_hook(self, config):
        for plugin in self.plugins:
            plugin.config_hook(config)

    def verify_package_hook(self, package_name, file_path):
        for plugin in self.plugins:
            plugin.verify_package_hook(package_name, file_path)

class PuppetPlugin:
    def __init__(self):
        self.puppet_state = {}

    def load_puppet_state(self, file_path):
        try:
            with open(file_path, 'r') as file:
                self.puppet_state = yaml.safe_load(file)
        except FileNotFoundError:
            print(f"Error: Puppet state file '{file_path}' not found.")
        except yaml.YAMLError as exc:
            print(f"Error parsing YAML file: {exc}")

    def config_hook(self, config):
        puppet_state_path = config.get('puppet_state_path')
        if puppet_state_path:
            self.load_puppet_state(puppet_state_path)

    def verify_package_hook(self, package_name, file_path):
        file_key = f"File[{file_path}]"
        if file_key in self.puppet_state:
            checksums = self.puppet_state[file_key].get('checksums', {})
            if checksums:
                actual_checksum = self.calculate_checksum(file_path, 'md5')
                expected_checksum = checksums.get('md5')
                if actual_checksum == expected_checksum:
                    print(f"Package '{package_name}': File '{file_path}' is verified.")
                else:
                    print(f"Package '{package_name}': File '{file_path}' checksum mismatch!")
            else:
                print(f"Package '{package_name}': No checksums found for '{file_path}'.")
        else:
            print(f"Package '{package_name}': File '{file_path}' not managed by Puppet.")

    def calculate_checksum(self, file_path, algorithm):
        hash_func = hashlib.new(algorithm)
        try:
            with open(file_path, 'rb') as file:
                for chunk in iter(lambda: file.read(4096), b""):
                    hash_func.update(chunk)
            return hash_func.hexdigest()
        except FileNotFoundError:
            print(f"Error: File '{file_path}' not found.")
            return None
```

### Step 2: Implement the Main Program

The main program will use the plugin system to verify packages.

```python
def main():
    plugin_system = PluginSystem()
    puppet_plugin = PuppetPlugin()
    plugin_system.register_plugin(puppet_plugin)

    # Configuration
    config = {
        'puppet_state_path': 'puppet_state.yaml'
    }
    plugin_system.config_hook(config)

    # Example package verification
    packages_to_verify = [
        {'name': 'example_package', 'file_path': '/path/to/file'}
    ]

    for package in packages_to_verify:
        plugin_system.verify_package_hook(package['name'], package['file_path'])

if __name__ == "__main__":
    main()
```

