class Solution:
    def backspace_compare(self, str1: str, str2: str) -> bool:
        def build_final_string(s: str) -> str:
            result = []
            for char in s:
                if char == '#':
                    if result:
                        result.pop()
                else:
                    result.append(char)
            return ''.join(result)

        return build_final_string(str1) == build_final_string(str2)

