    def test_equal_after_backspace(self):
        S = "ab##"
        T = "c#d#"
        sol = Solution()
        self.assertTrue(sol.backspace_compare(S, T))

    def test_equal_with_different_backspaces(self):
        S = "a##c"
        T = "#a#c"
        sol = Solution()
        self.assertTrue(sol.backspace_compare(S, T))

