import click

# Function to create a title with an underline
def create_title(text, underline_char='-', title_case=True):
    if title_case:
        text = text.title()
    underline = underline_char * len(text)
    return f"{text}\n{underline}"

# Function to create a boxed text
def create_box(text, border_char='*'):
    lines = text.split('\n')
    max_length = max(len(line) for line in lines)
    border = border_char * (max_length + 4)
    boxed_lines = [f"{border_char} {line.ljust(max_length)} {border_char}" for line in lines]
    return f"{border}\n" + "\n".join(boxed_lines) + f"\n{border}"

# Function to simulate an evaluation process
def simulate_evaluation(verbosity):
    results = {
        "command1": "success",
        "command2": "failure",
        "command3": "success"
    }
    if verbosity == "verbose":
        for command, result in results.items():
            click.echo(f"{command}: {result}")
    else:
        success_count = sum(1 for result in results.values() if result == "success")
        failure_count = len(results) - success_count
        click.echo(f"Summary: {success_count} succeeded, {failure_count} failed")

# Function to summarize an evaluation
def summarize_evaluation(results):
    success_count = sum(1 for result in results.values() if result == "success")
    failure_count = len(results) - success_count
    if success_count == len(results):
        click.echo("Evaluation was successful!")
    else:
        failed_commands = [cmd for cmd, res in results.items() if res == "failure"]
        click.echo(f"Evaluation failed for: {', '.join(failed_commands)}")

@click.group()
def cli():
    """CLI for generating styled text outputs."""
    pass

@cli.command()
@click.argument('text')
@click.option('--underline-char', default='-', help='Character to use for the underline.')
@click.option('--title-case', is_flag=True, help='Transform text to title case.')
def title(text, underline_char, title_case):
    """Print a title with an underline."""
    try:
        styled_title = create_title(text, underline_char, title_case)
        click.echo(styled_title)
    except Exception as e:
        click.echo(f"Error: {e}")

@cli.command()
@click.argument('text')
@click.option('--border-char', default='*', help='Character to use for the box border.')
def box(text, border_char):
    """Print text inside a box."""
    try:
        boxed_text = create_box(text, border_char)
        click.echo(boxed_text)
    except Exception as e:
        click.echo(f"Error: {e}")

@cli.command()
@click.option('--verbosity', type=click.Choice(['summary', 'verbose']), default='summary', help='Level of detail for evaluation output.')
def evaluation(verbosity):
    """Simulate an evaluation process."""
    try:
        simulate_evaluation(verbosity)
    except Exception as e:
        click.echo(f"Error: {e}")

@cli.command()
def summary():
    """Print a summary of the evaluation."""
    results = {
        "command1": "success",
        "command2": "failure",
        "command3": "success"
    }
    try:
        summarize_evaluation(results)
    except Exception as e:
        click.echo(f"Error: {e}")

if __name__ == '__main__':
    cli()
