        self.nombre = self._validate_str(nombre, "nombre")
        self.fechaPublicacion = self._validate_date(fechaPublicacion)
        self.generos = self._validate_list(generos, "generos", str)
        self.descripcion = self._validate_str(descripcion, "descripcion")
        self.albumsSimilares = self._validate_list(albumsSimilares, "albumsSimilares", Album)
        self.playsCanciones = self._validate_dict(playsCanciones, "playsCanciones", str, int)

    def _validate_str(self, value, name):
        if not isinstance(value, str):
            raise ValueError(f"{name} must be a string.")
        return value

    def _validate_date(self, value):
        if not isinstance(value, str):
            raise ValueError("fechaPublicacion must be a string.")
        if not re.match(r'^\d{4}-\d{2}-\d{2}$', value):
            raise ValueError("fechaPublicacion must be in the format 'YYYY-MM-DD'.")
        try:
            datetime.strptime(value, '%Y-%m-%d')
        except ValueError:
            raise ValueError("fechaPublicacion must be a valid date in the format 'YYYY-MM-DD'.")
        return value

    def _validate_list(self, value, name, element_type):
        if value is None:
            return []
        if not isinstance(value, list):
            raise ValueError(f"{name} must be a list.")
        if not all(isinstance(item, element_type) for item in value):
            raise ValueError(f"All elements in {name} must be of type {element_type.__name__}.")
        return value

    def _validate_dict(self, value, name, key_type, val_type):
        if value is None:
            return {}
        if not isinstance(value, dict):
            raise ValueError(f"{name} must be a dictionary.")
        if not all(isinstance(k, key_type) and isinstance(v, val_type) for k, v in value.items()):
            raise ValueError(f"All keys in {name} must be of type {key_type.__name__} and values of type {val_type.__name__}.")
        return value

    def agregarGenero(self, genero):
        if not isinstance(genero, str):
            raise ValueError("Genero must be a string.")
        if genero not in self.generos:
            self.generos.append(genero)

    def getAlbumsSimilares(self):
        return self.albumsSimilares

    def setAlbumsSimilares(self, albums):
        if not isinstance(albums, list):
            raise ValueError("albums must be a list.")
        if not all(isinstance(album, Album) for album in albums):
            raise ValueError("All elements in albums must be instances of Album.")
        self.albumsSimilares = albums

    def getPlaysCanciones(self):
        return self.playsCanciones

    def setPlaysCanciones(self, plays):
        if not isinstance(plays, dict):
            raise ValueError("plays must be a dictionary.")
        if not all(isinstance(k, str) and isinstance(v, int) and v >= 0 for k, v in plays.items()):
            raise ValueError("All keys in plays must be strings and values must be non-negative integers.")
        self.playsCanciones = plays

