class GetHolidayMixin:
    def get_holiday_by_id(self, id):
        for holiday in self.holidays:
            if holiday['id'] == id:
                return holiday
        return "Error: No holiday found with the provided id."

class DeleteHolidayMixin:
    def delete_holiday_by_id(self, id):
        for i, holiday in enumerate(self.holidays):
            if holiday['id'] == id:
                del self.holidays[i]
                return
        return "Error: No holiday found with the provided id."

class UpdateHolidayMixin:
    def update_holiday_by_id(self, id, new_data):
        if 'name' not in new_data and 'date' not in new_data:
            return "Error: new_data must contain at least 'name' or 'date'."

        for holiday in self.holidays:
            if holiday['id'] == id:
                if 'name' in new_data:
                    holiday['name'] = new_data['name']
                if 'date' in new_data:
                    holiday['date'] = new_data['date']
                return
        return "Error: No holiday found with the provided id."

class HolidayManager(GetHolidayMixin, DeleteHolidayMixin, UpdateHolidayMixin):
    def __init__(self):
        self.holidays = []

    def add_holiday(self, holiday):
        # Validate holiday dictionary
        if 'id' not in holiday or 'name' not in holiday or 'date' not in holiday:
            raise ValueError("Holiday must contain 'id', 'name', and 'date'.")
        self.holidays.append(holiday)

