```python
import logging
from enum import Enum, auto

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class DeviceState(Enum):
    ON = auto()
    OFF = auto()
    OPEN = auto()
    CLOSED = auto()
    UNAVAILABLE = auto()

class Device:
    def __init__(self, name):
        self.name = name
        self.state = DeviceState.UNAVAILABLE

    def set_state(self, state):
        if self.state == DeviceState.UNAVAILABLE:
            logging.error(f"Cannot change state of {self.name}. Device is unavailable.")
            raise Exception(f"Device {self.name} is unavailable.")
        self.state = state
        logging.info(f"{self.name} state changed to {self.state.name}")

    def get_state(self):
        return self.state

class Switch(Device):
    def __init__(self, name):
        super().__init__(name)

    def turn_on(self):
        self.set_state(DeviceState.ON)

    def turn_off(self):
        self.set_state(DeviceState.OFF)

    def toggle(self):
        if self.state == DeviceState.ON:
            self.turn_off()
        else:
            self.turn_on()

class Cover(Device):
    def __init__(self, name):
        super().__init__(name)

    def open_cover(self):
        self.set_state(DeviceState.OPEN)

    def close_cover(self):
        self.set_state(DeviceState.CLOSED)

class SmartHomeSystem:
    def __init__(self, config):
        self.devices = {}
        self.config = config

    def add_switch_as_cover(self, switch_name):
        switch = Switch(switch_name)
        cover = Cover(switch_name)
        self.devices[switch_name] = {'switch': switch, 'cover': cover}
        logging.info(f"Added switch '{switch_name}' as cover.")

    def toggle_switch(self, switch_name):
        device = self.devices.get(switch_name, {}).get('switch')
        if device:
            device.toggle()

    def open_cover(self, switch_name):
        device = self.devices.get(switch_name, {}).get('cover')
        if device:
            device.open_cover()

    def close_cover(self, switch_name):
        device = self.devices.get(switch_name, {}).get('cover')
        if device:
            device.close_cover()

    def turn_on_switch(self, switch_name):
        device = self.devices.get(switch_name, {}).get('switch')
        if device:
            device.turn_on()

    def turn_off_switch(self, switch_name):
        device = self.devices.get(switch_name, {}).get('switch')
        if device:
            device.turn_off()

    def get_device_state(self, switch_name):
        device_info = self.devices.get(switch_name, {})
        switch_state = device_info.get('switch', Device('unknown')).get_state()
        cover_state = device_info.get('cover', Device('unknown')).get_state()
        return {
            'switch': switch_state.name,
            'cover': cover_state.name
        }

# Unit tests
import unittest

class TestSmartHomeSystem(unittest.TestCase):
    def setUp(self):
        self.system = SmartHomeSystem(config={})
        self.system.add_switch_as_cover('LivingRoom')

    def test_initial_state(self):
        state = self.system.get_device_state('LivingRoom')
        self.assertEqual(state['switch'], 'UNAVAILABLE')
        self.assertEqual(state['cover'], 'UNAVAILABLE')

    def test_turn_on_switch(self):
        self.system.turn_on_switch('LivingRoom')
        state = self.system.get_device_state('LivingRoom')
        self.assertEqual(state['switch'], 'ON')
        self.assertEqual(state['cover'], 'OPEN')

    def test_turn_off_switch(self):
        self.system.turn_on_switch('LivingRoom')
        self.system.turn_off_switch('LivingRoom')
        state = self.system.get_device_state('LivingRoom')
        self.assertEqual(state['switch'], 'OFF')
        self.assertEqual(state['cover'], 'CLOSED')

    def test_toggle_switch(self):
        self.system.toggle_switch('LivingRoom')
        state = self.system.get_device_state('LivingRoom')
        self.assertEqual(state['switch'], 'ON')
        self.assertEqual(state['cover'], 'OPEN')

        self.system.toggle_switch('LivingRoom')
        state = self.system.get_device_state('LivingRoom')
        self.assertEqual(state['switch'], 'OFF')
        self.assertEqual(state['cover'], 'CLOSED')

    def test_unavailable_state(self):
        with self.assertRaises(Exception):
            self.system.devices['LivingRoom']['switch'].state = DeviceState.UNAVAILABLE
            self.system.turn_on_switch('LivingRoom')

if __name__ == '__main__':
    unittest.main()
```

