```python
import sqlite3
import logging
from datetime import datetime

class Persistence:
    def __init__(self, filepath):
        self.filepath = filepath
        self.connection = None
        self._initialize_database()

    def _initialize_database(self):
        try:
            self.connection = sqlite3.connect(self.filepath)
            cursor = self.connection.cursor()
            cursor.execute('''
                CREATE TABLE IF NOT EXISTS NotDelivered (
                    containerId TEXT PRIMARY KEY,
                    temperature INTEGER,
                    humidity INTEGER,
                    latitude REAL,
                    longitude REAL,
                    timestamp TEXT
                )
            ''')
            self.connection.commit()
        except sqlite3.Error as e:
            logging.error(f"Database error: {e}")
            if self.connection:
                self.connection.close()
                self.connection = None

    def insert(self, data):
        if not self._validate_data(data):
            logging.error("Invalid data structure or types.")
            return False

        try:
            cursor = self.connection.cursor()
            cursor.execute('''
                INSERT INTO NotDelivered (containerId, temperature, humidity, latitude, longitude, timestamp)
                VALUES (?, ?, ?, ?, ?, ?)
            ''', (
                data['containerId'],
                data['temperature'],
                data['humidity'],
                data['geo']['latitude'],
                data['geo']['longitude'],
                data['timestamp']
            ))
            self.connection.commit()
            return True
        except sqlite3.Error as e:
            logging.error(f"SQLite error: {e}")
            return False

    def _validate_data(self, data):
        if not isinstance(data, dict):
            return False
        required_keys = ['containerId', 'temperature', 'humidity', 'geo', 'timestamp']
        for key in required_keys:
            if key not in data:
                return False
        if not isinstance(data['containerId'], str):
            return False
        if not isinstance(data['temperature'], int):
            return False
        if not isinstance(data['humidity'], int):
            return False
        if not isinstance(data['geo'], dict):
            return False
        if 'latitude' not in data['geo'] or 'longitude' not in data['geo']:
            return False
        if not isinstance(data['geo']['latitude'], float):
            return False
        if not isinstance(data['geo']['longitude'], float):
            return False
        if not isinstance(data['timestamp'], str):
            return False
        try:
            datetime.fromisoformat(data['timestamp'])
        except ValueError:
            return False
        return True

    def close(self):
        if self.connection:
            try:
                self.connection.close()
            except sqlite3.Error as e:
                logging.error(f"Error closing the database connection: {e}")

# Example usage
if __name__ == "__main__":
    logging.basicConfig(level=logging.DEBUG)
