class Store:
    def __init__(self):
        """Initialize the store with an empty inventory."""
        self.inventory = {}

    def add_product(self, product_name, quantity):
        """Add a product to the store's inventory."""
        if product_name in self.inventory:
            self.inventory[product_name] += quantity
        else:
            self.inventory[product_name] = quantity

    def display_products(self):
        """Display all available products in the store."""
        if not self.inventory:
            print("No products available in the store.")
        else:
            print("Available products:")
            for product, quantity in self.inventory.items():
                print(f"{product}: {quantity} available")

    def borrow_product(self, product_name):
        """Allow a buyer to borrow a product if available."""
        if product_name in self.inventory and self.inventory[product_name] > 0:
            self.inventory[product_name] -= 1
            print(f"Product '{product_name}' borrowed successfully.")
            return True
        else:
            print(f"Product '{product_name}' is not available.")
            return False

    def return_product(self, product_name):
        """Allow a buyer to return a product, adding it back to the inventory."""
        if product_name in self.inventory:
            self.inventory[product_name] += 1
            print(f"Product '{product_name}' returned successfully.")
        else:
            self.inventory[product_name] = 1
            print(f"Product '{product_name}' added to inventory.")

class Buyer:
    def __init__(self, name):
        """Initialize a buyer with a name."""
        self.name = name

    def borrow(self, store, product_name):
        """Attempt to borrow a product from the store."""
        store.borrow_product(product_name)

    def return_product(self, store, product_name):
        """Return a product to the store."""
        store.return_product(product_name)

def main():
