```python
class Station:
    def __init__(self, sde_client, station_name):
        if not isinstance(station_name, str) or not station_name.strip():
            raise ValueError("Station name must be a non-empty string.")

        self.sde_client = sde_client
        self.station_name = station_name.strip()
        self.station_id = self.find_station_id()
        self.region_id = self.find_region_id()
        self.shorthand_name = self.generate_shorthand()

    def find_station_id(self):
        try:
            stations = self.sde_client.Station.getStations(stationName=self.station_name)
            if not stations:
                raise ValueError(f"Station '{self.station_name}' not found.")
            return stations[0].get('stationID')
        except Exception as e:
            raise RuntimeError(f"Failed to retrieve station ID: {e}")

    def find_region_id(self):
        try:
            stations = self.sde_client.Station.getStations(stationName=self.station_name)
            if not stations:
                raise ValueError(f"Station '{self.station_name}' not found.")
            return stations[0].get('regionID')
        except Exception as e:
            raise RuntimeError(f"Failed to retrieve region ID: {e}")

    def generate_shorthand(self):
        return self.station_name.split()[0]

    def get_station_name(self):
        return self.station_name

    def get_station_id(self):
        return self.station_id

    def get_region_id(self):
        return self.region_id

    def get_shorthand_name(self):
        return self.shorthand_name


class MockSDEClient:
    class Station:
        @staticmethod
        def getStations(stationName):
            # Mock data for testing
            mock_data = {
                "Alpha Station": {'stationID': 1, 'regionID': 101},
                "Beta Station": {'stationID': 2, 'regionID': 102},
                "Gamma Station": {'stationID': 3, 'regionID': 103},
            }
            return [mock_data.get(stationName)] if stationName in mock_data else []


# Unit tests
import unittest

class TestStation(unittest.TestCase):
    def setUp(self):
        self.mock_sde_client = MockSDEClient()

    def test_valid_station(self):
        station = Station(self.mock_sde_client, "Alpha Station")
        self.assertEqual(station.get_station_name(), "Alpha Station")
        self.assertEqual(station.get_station_id(), 1)
        self.assertEqual(station.get_region_id(), 101)
        self.assertEqual(station.get_shorthand_name(), "Alpha")

    def test_invalid_station_name(self):
        with self.assertRaises(ValueError):
            Station(self.mock_sde_client, "")

    def test_non_existent_station(self):
        with self.assertRaises(ValueError):
            Station(self.mock_sde_client, "NonExistent Station")

    def test_station_id_retrieval_failure(self):
        class FailingSDEClient:
            class Station:
                @staticmethod
                def getStations(stationName):
                    raise Exception("Database error")

        with self.assertRaises(RuntimeError):
            Station(FailingSDEClient(), "Alpha Station")

    def test_region_id_retrieval_failure(self):
        class FailingSDEClient:
            class Station:
                @staticmethod
                def getStations(stationName):
                    return []

        with self.assertRaises(RuntimeError):
            Station(FailingSDEClient(), "Alpha Station")

if __name__ == '__main__':
    unittest.main()
