```python
class AlbumService:
    def __init__(self):
        self.albums = []

    def add_record(self, title, artist, year, genre):
        if not isinstance(title, str) or not isinstance(artist, str) or not isinstance(genre, str):
            raise ValueError("Title, artist, and genre must be strings.")
        if not isinstance(year, int):
            raise ValueError("Year must be an integer.")

        album = {
            "title": title,
            "artist": artist,
            "year": year,
            "genre": genre
        }
        self.albums.append(album)
        return True

    def get_all_albums(self):
        return self.albums

    def search_by_option(self, option, value):
        if option not in ["title", "artist", "year", "genre"]:
            raise ValueError("Invalid search option.")

        results = []
        for album in self.albums:
            if str(album.get(option, '')).lower() == str(value).lower():
                results.append(album)
        return results


def main():
    album_service = AlbumService()

    while True:
        print("\nMusic Album Management System")
        print("1. Add a new album to the collection.")
        print("2. Get all albums in the collection.")
        print("3. Search for an album.")
        print("4. Quit the program.")

        try:
            choice = int(input("Enter your choice: "))
        except ValueError:
            print("Invalid input. Please enter a number between 1 and 4.")
            continue

        if choice == 1:
            try:
                title = input("Enter album title: ")
                artist = input("Enter artist name: ")
                year = int(input("Enter release year: "))
                genre = input("Enter genre: ")
                if album_service.add_record(title, artist, year, genre):
                    print("Album added successfully!")
            except ValueError as e:
                print(f"Error: {e}")

        elif choice == 2:
            albums = album_service.get_all_albums()
            if albums:
                for album in albums:
                    print(album)
            else:
                print("No albums in the collection.")

        elif choice == 3:
            print("Search by:")
            print("1. Title")
            print("2. Artist")
            print("3. Year")
            print("4. Genre")
            try:
                search_choice = int(input("Enter your choice: "))
                if search_choice not in [1, 2, 3, 4]:
                    raise ValueError("Invalid choice.")

                options = ["title", "artist", "year", "genre"]
                option = options[search_choice - 1]
                value = input(f"Enter {option}: ")

                if option == "year":
                    value = int(value)

                results = album_service.search_by_option(option, value)
                if results:
                    for album in results:
                        print(album)
                else:
                    print("No albums found.")
            except ValueError as e:
                print(f"Error: {e}")

        elif choice == 4:
            print("Exiting the program. Goodbye!")
            break

        else:
            print("Invalid choice. Please enter a number between 1 and 4.")


if __name__ == "__main__":
    main()
```

