import unittest

class TestGetTopNItems(unittest.TestCase):
    def test_valid_input(self):
        prices = {'item1': 45.50, 'item2': 35, 'item3': 41.30, 'item4': 55, 'item5': 24}
        result = get_top_n_items(prices, 3)
        expected = [('item4', 55), ('item1', 45.50), ('item3', 41.30)]
        self.assertEqual(result, expected)

    def test_empty_dictionary(self):
        prices = {}
        result = get_top_n_items(prices, 3)
        self.assertEqual(result, [])

    def test_n_greater_than_items(self):
        prices = {'item1': 45.50, 'item2': 35}
        result = get_top_n_items(prices, 5)
        expected = [('item1', 45.50), ('item2', 35)]
        self.assertEqual(result, expected)

    def test_invalid_first_argument(self):
        with self.assertRaises(ValueError):
            get_top_n_items("not_a_dict", 3)

    def test_invalid_n(self):
        prices = {'item1': 45.50, 'item2': 35}
        with self.assertRaises(ValueError):
            get_top_n_items(prices, -1)
        with self.assertRaises(ValueError):
            get_top_n_items(prices, 0)
        with self.assertRaises(ValueError):
            get_top_n_items(prices, "three")

if __name__ == "__main__":
    unittest.main()
