```python
import os
from ase import Atoms
import numpy as np

class ConfigMaker:
    def __init__(self):
        self.config_types = []
        self.lattice_vectors = None
        self.basis_atoms = []
        self.box_dimensions = None
        self.type_mappings = {}
        self.atoms_list = []

        self.parse_configtypes()
        self.parse_config()

    def parse_configtypes(self):
        try:
            with open('CONFIGTYPES', 'r') as f:
                self.config_types = [line.strip() for line in f if line.strip()]
        except FileNotFoundError:
            raise FileNotFoundError("CONFIGTYPES file is missing.")
        except Exception as e:
            raise ValueError(f"Error reading CONFIGTYPES file: {e}")

        if not self.config_types:
            raise ValueError("CONFIGTYPES file is empty or improperly formatted.")

    def parse_config(self):
        try:
            with open('LATVEC', 'r') as f:
                self.lattice_vectors = np.array([list(map(float, line.split())) for line in f if line.strip()])
        except FileNotFoundError:
            raise FileNotFoundError("LATVEC file is missing.")
        except Exception as e:
            raise ValueError(f"Error reading LATVEC file: {e}")

        if self.lattice_vectors.shape != (3, 3):
            raise ValueError("LATVEC file must contain exactly three 3D vectors.")

        try:
            with open('BASIS', 'r') as f:
                self.basis_atoms = [line.strip().split() for line in f if line.strip()]
        except FileNotFoundError:
            raise FileNotFoundError("BASIS file is missing.")
        except Exception as e:
            raise ValueError(f"Error reading BASIS file: {e}")

        if not self.basis_atoms:
            raise ValueError("BASIS file is empty or improperly formatted.")

        try:
            with open('BOX', 'r') as f:
                self.box_dimensions = np.array(list(map(float, f.readline().strip().split())))
        except FileNotFoundError:
            raise FileNotFoundError("BOX file is missing.")
        except Exception as e:
            raise ValueError(f"Error reading BOX file: {e}")

        if self.box_dimensions.shape != (3,):
            raise ValueError("BOX file must contain exactly three dimensions.")

        try:
            with open('TYPEMAP', 'r') as f:
                self.type_mappings = {line.split()[0]: line.split()[1] for line in f if line.strip()}
        except FileNotFoundError:
            raise FileNotFoundError("TYPEMAP file is missing.")
        except Exception as e:
            raise ValueError(f"Error reading TYPEMAP file: {e}")

        if not self.type_mappings:
            raise ValueError("TYPEMAP file is empty or improperly formatted.")

    def add(self, symbols, positions, box):
        if len(symbols) != len(positions):
            raise ValueError("The number of symbols must match the number of positions.")

        # Convert positions to a numpy array for ASE compatibility
        positions = np.array(positions)
        box = np.array(box)

        # Create an Atoms object and add it to the list
        atoms = Atoms(symbols=symbols, positions=positions, cell=box, pbc=True)
        self.atoms_list.append(atoms)

    def write_configs(self, filename):
        if not self.atoms_list:
            raise ValueError("No configurations to write.")

        with open(filename, 'w') as f:
            for atoms in self.atoms_list:
                f.write(f"{len(atoms)}\n")
                f.write(" ".join(atoms.get_chemical_symbols()) + "\n")
                for pos in atoms.get_positions():
                    f.write(" ".join(map(str, pos)) + "\n")
                f.write(" ".join(map(str, atoms.get_cell().flatten())) + "\n")

