```python
import ast
import astor
from fractions import Fraction
from diofant.core.symbol import Symbol

class CodeTransformer(ast.NodeTransformer):
    def __init__(self, defined_names=None):
        if defined_names is None:
            defined_names = set()
        self.defined_names = defined_names

    def visit_BinOp(self, node):
        self.generic_visit(node)
        if isinstance(node.op, ast.Div) and isinstance(node.left, ast.Num) and isinstance(node.right, ast.Num):
            # Integer division transformation
            return ast.Call(
                func=ast.Name(id='Fraction', ctx=ast.Load()),
                args=[node.left, node.right],
                keywords=[]
            )
        return node

    def visit_Num(self, node):
        # Float rationalization
        if isinstance(node.n, float):
            return ast.Call(
                func=ast.Name(id='Fraction', ctx=ast.Load()),
                args=[ast.Constant(value=node.n)],
                keywords=[]
            )
        return node

    def visit_Name(self, node):
        if isinstance(node.ctx, ast.Load) and node.id not in self.defined_names:
            # Automatic symbol definition
            self.defined_names.add(node.id)
            return ast.Call(
                func=ast.Name(id='Symbol', ctx=ast.Load()),
                args=[ast.Constant(value=node.id)],
                keywords=[]
            )
        return node

    def visit_Str(self, node):
        # Unicode identifiers normalization
        if any(ord(c) > 127 for c in node.s):
            normalized = ''.join('_{}'.format(ord(c)) if ord(c) > 127 else c for c in node.s)
            return ast.Constant(value=normalized)
        return node

def transform_code(code, defined_names=None):
    tree = ast.parse(code)
    transformer = CodeTransformer(defined_names=defined_names)
    transformed_tree = transformer.visit(tree)
    ast.fix_missing_locations(transformed_tree)
    return astor.to_source(transformed_tree)

# Example usage
code = """
x = 5 / 2
y = 3.5
z = x + y
print(z)
"""

transformed_code = transform_code(code)
print(transformed_code)
```

