```python
class Model:
    """Base class for vehicle models."""
    pass

class VmsProgram:
    """Class representing a maintenance program."""

    def __init__(self, name):
        self.name = name
        self.services = []
        self.inspections = []

    def add_service(self, service):
        """Add a service to the maintenance program."""
        if isinstance(service, str):
            self.services.append(service)
        else:
            raise ValueError("Service must be a string.")

    def add_inspection(self, inspection):
        """Add an inspection to the maintenance program."""
        if isinstance(inspection, str):
            self.inspections.append(inspection)
        else:
            raise ValueError("Inspection must be a string.")

    def get_details(self):
        """Return the details of the maintenance program."""
        return {
            'name': self.name,
            'services': self.services,
            'inspections': self.inspections
        }

class FleetVehicleModel(Model):
    """Class representing a vehicle model with an associated maintenance program."""

    def __init__(self, model_name):
        self.model_name = model_name
        self.program_id = None

    def assign_program(self, program):
        """Assign a maintenance program to the vehicle model."""
        if not isinstance(program, VmsProgram):
            raise ValueError("Assigned program must be an instance of VmsProgram.")
        self.program_id = program

    def get_program_details(self):
        """Retrieve the details of the associated maintenance program."""
        if self.program_id is None:
            raise ValueError("No maintenance program assigned.")
        return self.program_id.get_details()

# Unit tests
import unittest

class TestFleetVehicleModel(unittest.TestCase):

    def setUp(self):
        self.vehicle_model = FleetVehicleModel("Model X")
        self.program = VmsProgram("Standard Maintenance")
        self.program.add_service("Oil Change")
        self.program.add_inspection("Brake Inspection")

    def test_assign_program(self):
        self.vehicle_model.assign_program(self.program)
        self.assertEqual(self.vehicle_model.program_id, self.program)

    def test_assign_invalid_program(self):
        with self.assertRaises(ValueError):
            self.vehicle_model.assign_program("Not a Program")

    def test_get_program_details(self):
        self.vehicle_model.assign_program(self.program)
        details = self.vehicle_model.get_program_details()
        expected_details = {
            'name': 'Standard Maintenance',
            'services': ['Oil Change'],
            'inspections': ['Brake Inspection']
        }
        self.assertEqual(details, expected_details)

    def test_get_program_details_no_program(self):
        with self.assertRaises(ValueError):
            self.vehicle_model.get_program_details()

class TestVmsProgram(unittest.TestCase):

    def setUp(self):
        self.program = VmsProgram("Extended Maintenance")

    def test_add_service(self):
        self.program.add_service("Tire Rotation")
        self.assertIn("Tire Rotation", self.program.services)

    def test_add_invalid_service(self):
        with self.assertRaises(ValueError):
            self.program.add_service(123)

    def test_add_inspection(self):
        self.program.add_inspection("Engine Check")
        self.assertIn("Engine Check", self.program.inspections)

    def test_add_invalid_inspection(self):
        with self.assertRaises(ValueError):
            self.program.add_inspection(456)

if __name__ == "__main__":
    unittest.main()
```

