```python
import re

# Simulating the register decorator
def register(cls):
    # This is a placeholder for the actual registration logic
    print(f"Registering {cls.__name__}")
    return cls

# Base classes (stubs for demonstration)
class DescriptionWidget:
    pass

class ValueWidget:
    pass

class CoreWidget:
    pass

@register
class ColorPicker(DescriptionWidget, ValueWidget, CoreWidget):
    def __init__(self, value="black", concise=False, disabled=False):
        self._view_name = "ColorPickerView"
        self._model_name = "ColorPickerModel"
        self.value = value
        self.concise = concise
        self.disabled = disabled

    @property
    def value(self):
        return self._value

    @value.setter
    def value(self, val):
        if not self._is_valid_color(val):
            raise ValueError(f"Invalid color format: {val}")
        self._value = val

    @property
    def concise(self):
        return self._concise

    @concise.setter
    def concise(self, val):
        self._concise = val

    @property
    def disabled(self):
        return self._disabled

    @disabled.setter
    def disabled(self, val):
        self._disabled = val

    def _is_valid_color(self, color):
        # Check for named colors
        named_colors = {
            "black", "white", "red", "green", "blue", "yellow", "cyan", "magenta", "gray", "silver", "maroon", "olive", "purple", "teal", "navy", "lime", "aqua", "fuchsia", "limegreen"
        }
        if color in named_colors:
            return True
        # Check for hex color codes
        hex_pattern = re.compile(r'^#(?:[0-9a-fA-F]{3}){1,2}$')
        return bool(hex_pattern.match(color))

# Test cases
def test_color_picker():
    # Test valid named color
    cp = ColorPicker()
    cp.value = "red"
    assert cp.value == "red", "Test failed: Named color 'red'"

    # Test valid hex color
    cp.value = "#FF0000"
    assert cp.value == "#FF0000", "Test failed: Hex color '#FF0000'"

    # Test valid short hex color
    cp.value = "#F00"
    assert cp.value == "#F00", "Test failed: Short hex color '#F00'"

    # Test invalid color
    try:
        cp.value = "invalidcolor"
        assert False, "Test failed: Invalid color should raise ValueError"
    except ValueError:
        pass

    # Test concise attribute
    cp.concise = True
    assert cp.concise is True, "Test failed: Concise attribute"

    # Test disabled attribute
    cp.disabled = True
    assert cp.disabled is True, "Test failed: Disabled attribute"

    print("All tests passed.")

# Run tests
test_color_picker()
