To design the `create_and_cleanup_vmax_volume` function, we need to follow the specifications closely. We'll use Python's `yaml` library to read and validate the configuration file, and we'll assume the existence of some helper functions and classes to interact with the EMC VMAX storage array. Here's a complete implementation:

```python
import yaml
import math
import requests

class VMAXError(Exception):
    pass

def _read_vmax_yaml(file_path):
    try:
        with open(file_path, 'r') as file:
            config = yaml.safe_load(file)

        required_fields = ['api_url', 'username', 'password', 'allocation_unit']
        for field in required_fields:
            if field not in config:
                raise VMAXError(f"Missing required field in YAML: {field}")

        return config
    except yaml.YAMLError as e:
        raise VMAXError(f"Error parsing YAML file: {e}")
    except FileNotFoundError:
        raise VMAXError("YAML configuration file not found.")

def vmax_allocation_unit(size_in_gb, allocation_unit):
    return math.ceil(size_in_gb / allocation_unit) * allocation_unit

def create_volume(api_url, auth, size_in_gb):
    headers = {'Content-Type': 'application/json'}
    payload = {'size': size_in_gb}
    response = requests.post(f"{api_url}/volumes", json=payload, headers=headers, auth=auth)

    if response.status_code != 201:
        raise VMAXError(f"Failed to create volume: {response.text}")

    return response.json()['id']

def delete_volume(api_url, auth, volume_id):
    headers = {'Content-Type': 'application/json'}
    response = requests.delete(f"{api_url}/volumes/{volume_id}", headers=headers, auth=auth)

    if response.status_code != 204:
        raise VMAXError(f"Failed to delete volume: {response.text}")

def create_and_cleanup_vmax_volume(size_in_gb, test_case):
    if not isinstance(size_in_gb, int) or size_in_gb <= 0:
        raise ValueError("Size must be a positive integer.")

    try:
        config = _read_vmax_yaml('vmax_config.yaml')
        api_url = config['api_url']
        username = config['username']
        password = config['password']
        allocation_unit = config['allocation_unit']

        auth = (username, password)
        size_in_allocation_units = vmax_allocation_unit(size_in_gb, allocation_unit)

        volume_id = create_volume(api_url, auth, size_in_allocation_units)

        def cleanup():
            try:
                delete_volume(api_url, auth, volume_id)
            except VMAXError as e:
                print(f"Error during cleanup: {e}")

        test_case.addCleanup(cleanup)

        return volume_id

    except VMAXError as e:
        print(f"Error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

# Unit tests
def test_create_and_cleanup_vmax_volume():
    class MockTestCase:
        def __init__(self):
            self.cleanup_callbacks = []

        def addCleanup(self, callback):
            self.cleanup_callbacks.append(callback)

        def run_cleanups(self):
            for callback in self.cleanup_callbacks:
                callback()

    # Mocking the requests.post and requests.delete for testing
    original_post = requests.post
    original_delete = requests.delete

    def mock_post(url, json, headers, auth):
        if 'volumes' in url:
            return MockResponse(201, {'id': 'vol-123'})
        raise VMAXError("Unexpected URL")

    def mock_delete(url, headers, auth):
        if 'volumes/vol-123' in url:
            return MockResponse(204)
        raise VMAXError("Unexpected URL")

    class MockResponse:
        def __init__(self, status_code, json_data=None):
            self.status_code = status_code
            self.json_data = json_data

        def json(self):
            return self.json_data

    requests.post = mock_post
    requests.delete = mock_delete

    test_case = MockTestCase()
    volume_id = create_and_cleanup_vmax_volume(10, test_case)
    assert volume_id == 'vol-123', "Volume ID should be 'vol-123'"

    test_case.run_cleanups()
    print("Test passed: Volume created and cleaned up successfully.")

test_create_and_cleanup_vmax_volume()
```

