To design the "GemSwap" match-3 puzzle game using Python and object-oriented programming principles, we'll break down the game into several classes and methods. This will ensure a clear code structure and modularity. Here's a basic implementation:

```python
import random

class Gem:
    COLORS = ['red', 'green', 'blue', 'yellow', 'purple']

    def __init__(self):
        self.color = random.choice(self.COLORS)

    def __repr__(self):
        return self.color[0].upper()

class Grid:
    def __init__(self, size=8):
        self.size = size
        self.grid = [[Gem() for _ in range(size)] for _ in range(size)]
        self.score = 0

    def __repr__(self):
        return '\n'.join([' '.join([str(gem) for gem in row]) for row in self.grid])

    def swap(self, x1, y1, x2, y2):
        if abs(x1 - x2) + abs(y1 - y2) == 1:
            self.grid[x1][y1], self.grid[x2][y2] = self.grid[x2][y2], self.grid[x1][y1]
            return True
        return False

    def find_matches(self):
        matches = []
        # Check horizontal matches
        for x in range(self.size):
            for y in range(self.size - 2):
                if self.grid[x][y].color == self.grid[x][y+1].color == self.grid[x][y+2].color:
                    matches.append((x, y))
                    matches.append((x, y+1))
                    matches.append((x, y+2))
        # Check vertical matches
        for y in range(self.size):
            for x in range(self.size - 2):
                if self.grid[x][y].color == self.grid[x+1][y].color == self.grid[x+2][y].color:
                    matches.append((x, y))
                    matches.append((x+1, y))
                    matches.append((x+2, y))
        return matches

    def remove_matches(self, matches):
        for x, y in matches:
            self.grid[x][y] = None
        self.score += len(matches) // 3
        self.drop_gems()
        self.fill_grid()

    def drop_gems(self):
        for y in range(self.size):
            empty_slots = [x for x in range(self.size) if self.grid[x][y] is None]
            for x in empty_slots:
                for above_x in range(x, 0, -1):
                    self.grid[above_x][y] = self.grid[above_x-1][y]
                self.grid[0][y] = Gem()

    def fill_grid(self):
        for x in range(self.size):
            for y in range(self.size):
                if self.grid[x][y] is None:
                    self.grid[x][y] = Gem()

    def reshuffle(self):
        for x in range(self.size):
            for y in range(self.size):
                self.grid[x][y] = Gem()

    def is_move_possible(self):
        for x in range(self.size):
            for y in range(self.size):
                if x < self.size - 1 and self.grid[x][y].color == self.grid[x+1][y].color:
                    return True
                if y < self.size - 1 and self.grid[x][y].color == self.grid[x][y+1].color:
                    return True
        return False

class Game:
    def __init__(self):
        self.grid = Grid()

    def play(self):
        while True:
            print(self.grid)
            print(f"Score: {self.grid.score}")
            try:
                x1, y1, x2, y2 = map(int, input("Enter swap positions (x1 y1 x2 y2): ").split())
                if self.grid.swap(x1, y1, x2, y2):
                    matches = self.grid.find_matches()
                    if matches:
                        self.grid.remove_matches(matches)
                    else:
                        self.grid.swap(x2, y2, x1, y1)  # Swap back if no match
                if not self.grid.is_move_possible():
                    print("No moves possible, reshuffling...")
                    self.grid.reshuffle()
            except Exception as e:
                print(f"Invalid input: {e}")

if __name__ == "__main__":
    game = Game()
    game.play()
```

### Explanation:

1. **Gem Class**: Represents a single gem with a random color.

2. **Grid Class**: Manages the 8x8 grid of gems. It includes methods to swap gems, find matches, remove matches, drop gems, fill the grid, reshuffle, and check if moves are possible.

3. **Game Class**: Manages the game loop, user input, and game state.

4. **Game Loop**: Continuously prompts the player for input, processes swaps, checks for matches, and updates the grid and score. If no moves are possible, it reshuffles the grid.

This implementation provides a basic structure for the "GemSwap" game, focusing on modularity and clear code organization.

