        self.id = id
        self.text = text
        self.created_at = created_at
        self.user_id = user_id

    @classmethod
    def from_dict(cls, data):
        try:
            tweet_id = data['id']
            text = data['text']
            created_at_str = data['created_at']
            user_id = data['user_id']

            # Validate and parse the created_at date
            created_at = datetime.fromisoformat(created_at_str)

            return cls(tweet_id, text, created_at, user_id)
        except KeyError as e:
            raise KeyError(f"Missing key in tweet data: {e}")
        except ValueError as e:
            raise ValueError(f"Invalid date format for created_at: {e}")

    def to_dict(self):
        return {
            'id': self.id,
            'text': self.text,
            'created_at': self.created_at.isoformat(),
            'user_id': self.user_id
        }

class Tweets:
