```python
import torch
import torch.nn as nn
import torch.nn.functional as F

class GPP(nn.Module):
    def __init__(self, gpp_type, levels, pool_type='avg_pool'):
        super(GPP, self).__init__()

        if gpp_type not in ['spp', 'tpp', 'gpp']:
            raise ValueError(f"Unknown gpp_type: {gpp_type}. Supported types are 'spp', 'tpp', 'gpp'.")

        if pool_type not in ['max_pool', 'avg_pool']:
            raise ValueError(f"Unknown pool_type: {pool_type}. Supported types are 'max_pool', 'avg_pool'.")

        self.gpp_type = gpp_type
        self.levels = levels
        self.pool_type = pool_type

        if gpp_type == 'gpp' and not (isinstance(levels, tuple) and len(levels) == 2):
            raise ValueError("For 'gpp', levels must be a tuple of two lists.")

        self.pooling_layer = nn.AdaptiveMaxPool2d if pool_type == 'max_pool' else nn.AdaptiveAvgPool2d

    def forward(self, x, mask=None):
        if self.gpp_type == 'spp':
            return self._spatial_pyramid_pooling(x, mask)
        elif self.gpp_type == 'tpp':
            return self._temporal_pyramid_pooling(x, mask)
        elif self.gpp_type == 'gpp':
            return self._generic_pyramid_pooling(x, mask)
        else:
            raise ValueError(f"Unsupported gpp_type: {self.gpp_type}")

    def _spatial_pyramid_pooling(self, x, mask=None):
        pooled_outputs = []
        for level in self.levels:
            pool = self.pooling_layer(level)
            pooled = pool(x)
            pooled_outputs.append(pooled.view(pooled.size(0), -1))
        return torch.cat(pooled_outputs, dim=1)

    def _temporal_pyramid_pooling(self, x, mask=None):
        # Assuming x is of shape (batch, channels, time, height, width)
        batch, channels, time, height, width = x.size()
        x = x.view(batch, channels, time, -1)  # Flatten spatial dimensions
        pooled_outputs = []
        for level in self.levels:
            pool = self.pooling_layer(level)
            pooled = pool(x)
            pooled_outputs.append(pooled.view(pooled.size(0), -1))
        return torch.cat(pooled_outputs, dim=1)

    def _generic_pyramid_pooling(self, x, mask=None):
        spatial_levels, temporal_levels = self.levels
        pooled_outputs = []

        # Spatial pooling
        for level in spatial_levels:
            pool = self.pooling_layer(level)
            pooled = pool(x)
            pooled_outputs.append(pooled.view(pooled.size(0), -1))

        # Temporal pooling
        batch, channels, time, height, width = x.size()
        x = x.view(batch, channels, time, -1)  # Flatten spatial dimensions
        for level in temporal_levels:
            pool = self.pooling_layer(level)
            pooled = pool(x)
            pooled_outputs.append(pooled.view(pooled.size(0), -1))

        return torch.cat(pooled_outputs, dim=1)

