To create the `AsyncRavenClient` class that extends the functionality of `raven.base.Client` for asynchronous error message sending using Tornado's asynchronous I/O loop, we need to integrate Tornado's `AsyncHTTPClient` for non-blocking HTTP requests. Below is the implementation of the `AsyncRavenClient` class along with unit tests using Tornado's testing framework.

### Implementation of `AsyncRavenClient`

```python
import raven
from tornado import ioloop, httpclient, testing
from tornado.concurrent import Future

class AsyncRavenClient(raven.base.Client):
    def __init__(self, dsn, timeout=10, verify_ssl=True, ca_certs=None):
        super(AsyncRavenClient, self).__init__(dsn, timeout=timeout, verify_ssl=verify_ssl, ca_certs=ca_certs)
        self._http_client = httpclient.AsyncHTTPClient()
        self._successful_send_callback = None
        self._failed_send_callback = None

    async def captureMessage(self, message):
        try:
            response = await self._http_client.fetch(
                self._build_url(),
                method='POST',
                body=self._build_body(message),
                headers=self._build_headers(),
                request_timeout=self._timeout
            )
            if self._successful_send_callback:
                self._successful_send_callback()
        except httpclient.HTTPError as e:
            if self._failed_send_callback:
                self._failed_send_callback()

    def _successful_send(self, callback):
        self._successful_send_callback = callback

    def _failed_send(self, callback):
        self._failed_send_callback = callback

    def _build_url(self):
        # Implement URL building logic based on DSN
        return self._dsn.url

    def _build_body(self, message):
        # Implement message body building logic
        return self._message_to_json(message)

    def _build_headers(self):
        # Implement headers building logic
        return {'Content-Type': 'application/json'}

    def _message_to_json(self, message):
        # Convert message to JSON format
        return raven.message.Message(message).to_json()
```

### Unit Tests for `AsyncRavenClient`

