class TestAsyncRavenClient(testing.AsyncTestCase):
    def setUp(self):
        super(TestAsyncRavenClient, self).setUp()
        self.dsn = raven.dsn.DSN('https://public_key:private_key@sentry.io/1')
        self.client = AsyncRavenClient(self.dsn)

    def test_http_client_instance(self):
        self.assertIsInstance(self.client._http_client, httpclient.AsyncHTTPClient)

    @testing.gen_test
    def test_capture_message_sends_correct_parameters(self):
        message = "Test message"
        response_future = Future()

        def on_successful_send():
            response_future.set_result(True)

        self.client._successful_send(on_successful_send)

        # Mock the fetch method to simulate a successful response
        self.client._http_client.fetch = lambda *args, **kwargs: response_future

        yield self.client.captureMessage(message)
        self.assertTrue(response_future.result())

    @testing.gen_test
    def test_successful_send_callback(self):
        message = "Test message"
        successful_called = False

        def on_successful_send():
            nonlocal successful_called
            successful_called = True

        self.client._successful_send(on_successful_send)

        # Mock the fetch method to simulate a successful response
        self.client._http_client.fetch = lambda *args, **kwargs: Future().set_result(None)

        yield self.client.captureMessage(message)
        self.assertTrue(successful_called)

    @testing.gen_test
    def test_failed_send_callback(self):
        message = "Test message"
        failed_called = False

        def on_failed_send():
            nonlocal failed_called
            failed_called = True

        self.client._failed_send(on_failed_send)

        # Mock the fetch method to simulate a failed response
        self.client._http_client.fetch = lambda *args, **kwargs: Future().set_exception(httpclient.HTTPError(500))

        yield self.client.captureMessage(message)
        self.assertTrue(failed_called)

if __name__ == '__main__':
    testing.main()
```

