```python
import copy

class Quixo:
    def __init__(self):
        self.board = [[i + 5 * j + 1 for i in range(5)] for j in range(5)]
        self.player = 'O'
        self.opponent = 'X'
        self.target_line = ['O'] * 5

    def print_board(self):
        for row in self.board:
            print(' '.join(str(x) for x in row))
        print()

    def is_valid_move(self, piece, target):
        if piece < 1 or piece > 25 or target < 1 or target > 25:
            return False
        piece_row, piece_col = divmod(piece - 1, 5)
        target_row, target_col = divmod(target - 1, 5)
        if piece_row == target_row or piece_col == target_col:
            if abs(piece_row - target_row) + abs(piece_col - target_col) == 1:
                return True
        return False

    def make_move(self, piece, target, player):
        piece_row, piece_col = divmod(piece - 1, 5)
        target_row, target_col = divmod(target - 1, 5)
        if not self.is_valid_move(piece, target):
            return False
        if self.board[target_row][target_col] not in [player, ' ']:
            return False
        self.board[piece_row][piece_col], self.board[target_row][target_col] = self.board[target_row][target_col], self.board[piece_row][piece_col]
        return True

    def check_win(self):
        for row in self.board:
            if row == self.target_line:
                return True
        for col in range(5):
            if [self.board[row][col] for row in range(5)] == self.target_line:
                return True
        if [self.board[i][i] for i in range(5)] == self.target_line:
            return True
        if [self.board[i][4 - i] for i in range(5)] == self.target_line:
            return True
        return False

    def get_possible_moves(self, player):
        moves = []
        for piece in range(1, 26):
            piece_row, piece_col = divmod(piece - 1, 5)
            if piece_row in [0, 4] or piece_col in [0, 4]:
                for target in range(1, 26):
                    if self.is_valid_move(piece, target):
                        new_board = copy.deepcopy(self.board)
                        new_board[piece_row][piece_col], new_board[divmod(target - 1, 5)] = new_board[divmod(target - 1, 5)], new_board[piece_row][piece_col]
                        moves.append((piece, target, new_board))
        return moves

    def alpha_beta(self, depth, alpha, beta, maximizing_player):
        if depth == 0 or self.check_win():
            return self.evaluate(), None

        if maximizing_player:
            max_eval = float('-inf')
            best_move = None
            for piece, target, new_board in self.get_possible_moves(self.player):
                self.board = new_board
                eval, _ = self.alpha_beta(depth - 1, alpha, beta, False)
                self.board = copy.deepcopy(self.previous_board)
                if eval > max_eval:
                    max_eval = eval
                    best_move = (piece, target)
                alpha = max(alpha, eval)
                if beta <= alpha:
                    break
            return max_eval, best_move
        else:
            min_eval = float('inf')
            best_move = None
            for piece, target, new_board in self.get_possible_moves(self.opponent):
                self.board = new_board
                eval, _ = self.alpha_beta(depth - 1, alpha, beta, True)
                self.board = copy.deepcopy(self.previous_board)
                if eval < min_eval:
                    min_eval = eval
                    best_move = (piece, target)
                beta = min(beta, eval)
                if beta <= alpha:
                    break
            return min_eval, best_move

    def evaluate(self):
        if self.check_win():
            return 1000
        return 0

    def play(self):
        while True:
            self.print_board()
            if self.player == 'O':
                self.previous_board = copy.deepcopy(self.board)
