from abc import ABC, abstractmethod
from cryptography.fernet import Fernet
import datetime

# Base classes for basic data types
class String(str):
    pass

class Decimal(float):
    pass

class Date(datetime.date):
    pass

class DateTime(datetime.datetime):
    pass

class IncompleteDate:
    def __init__(self, year, month=None, day=None):
        self.year = year
        self.month = month
        self.day = day

# Custom exception for unsupported data types
class UnsupportedDataTypeError(Exception):
    pass

# Base Secure class
class Secure(ABC):
    def __init__(self, value, encryption_key, encryption_level=1):
        self.encryption_key = encryption_key
        self.fernet = Fernet(encryption_key)
        self.encryption_level = encryption_level
        self.encrypted_value = None
        self.set_value(value)

    def set_value(self, value):
        if isinstance(value, str) and value.startswith("ENC:"):
            self.encrypted_value = value
        else:
            self.encrypted_value = self.encrypt(value)

    def encrypt(self, value):
        return f"ENC:{self.fernet.encrypt(str(value).encode()).decode()}"

    def decrypt(self, encrypted_value):
        return self.fernet.decrypt(encrypted_value[4:].encode()).decode()

    def get_value(self, access_level):
        if access_level < self.encryption_level:
            raise PermissionError("Access level too low to decrypt value.")
        decrypted_value = self.decrypt(self.encrypted_value)
        return self.get_typed_value(decrypted_value)

    @abstractmethod
    def get_typed_value(self, value):
        pass

# SecureString class
class SecureString(Secure, String):
    def get_typed_value(self, value):
        return String(value)

# SecureDecimal class
class SecureDecimal(Secure, Decimal):
    def get_typed_value(self, value):
        return Decimal(value)

# SecureDate class
class SecureDate(Secure, Date):
    def get_typed_value(self, value):
        return Date.fromisoformat(value)

# SecureDateTime class
class SecureDateTime(Secure, DateTime):
    def get_typed_value(self, value):
        return DateTime.fromisoformat(value)

# SecureIncompleteDate class
class SecureIncompleteDate(Secure, IncompleteDate):
    def get_typed_value(self, value):
        parts = value.split('-')
        year = int(parts[0])
        month = int(parts[1]) if len(parts) > 1 else None
        day = int(parts[2]) if len(parts) > 2 else None
        return IncompleteDate(year, month, day)

# Factory function to create secure objects
def create_secure_object(value, encryption_key, encryption_level=1):
    if isinstance(value, str):
        return SecureString(value, encryption_key, encryption_level)
    elif isinstance(value, float):
        return SecureDecimal(value, encryption_key, encryption_level)
    elif isinstance(value, datetime.date) and not isinstance(value, datetime.datetime):
        return SecureDate(value, encryption_key, encryption_level)
    elif isinstance(value, datetime.datetime):
        return SecureDateTime(value, encryption_key, encryption_level)
    elif isinstance(value, IncompleteDate):
        return SecureIncompleteDate(f"{value.year}-{'%02d' % value.month if value.month else ''}-{'%02d' % value.day if value.day else ''}", encryption_key, encryption_level)
    else:
        raise UnsupportedDataTypeError(f"Unsupported data type: {type(value)}")

# Unit tests
def test_secure_string():
    key = Fernet.generate_key()
    secure_str = create_secure_object("Hello, World!", key)
    assert secure_str.get_value(1) == "Hello, World!"

def test_secure_decimal():
    key = Fernet.generate_key()
    secure_dec = create_secure_object(123.45, key)
    assert secure_dec.get_value(1) == 123.45

def test_secure_date():
    key = Fernet.generate_key()
    secure_date = create_secure_object(datetime.date(2023, 10, 5), key)
    assert secure_date.get_value(1) == datetime.date(2023, 10, 5)

def test_secure_datetime():
    key = Fernet.generate_key()
    secure_dt = create_secure_object(datetime.datetime(2023, 10, 5, 14, 30), key)
    assert secure_dt.get_value(1) == datetime.datetime(2023, 10, 5, 14, 30)

def test_secure_incomplete_date():
    key = Fernet.generate_key()
    secure_inc_date = create_secure_object(IncompleteDate(2023, 10), key)
    assert secure_inc_date.get_value(1).year == 2023
    assert secure_inc_date.get_value(1).month == 10

# Run tests
test_secure_string()
test_secure_decimal()
test_secure_date()
test_secure_datetime()
test_secure_incomplete_date()

print("All tests passed.")
