import os
import shutil
import xml.etree.ElementTree as ET
import re

# Define namespaces for EAD parsing
EAD_NAMESPACES = {
    'ead': 'urn:isbn:1-931666-22-9'
}

def parse_ead_files(ead_dir):
    call_numbers = {}
    for filename in os.listdir(ead_dir):
        if filename.endswith('.xml'):
            try:
                tree = ET.parse(os.path.join(ead_dir, filename))
                root = tree.getroot()
                unitid = root.find('.//ead:unitid', EAD_NAMESPACES)
                eadid = root.find('.//ead:eadid', EAD_NAMESPACES)
                if unitid is not None and eadid is not None:
                    call_number = unitid.text
                    collection_id = eadid.text
                    call_numbers[call_number] = collection_id
            except ET.ParseError as e:
                print(f"Error parsing {filename}: {e}")
    return call_numbers

def parse_marc_record(marc_file, call_numbers):
    try:
        tree = ET.parse(marc_file)
        root = tree.getroot()
        ead_link = None
        call_number = None

        for datafield in root.findall('.//datafield'):
            tag = datafield.get('tag')
            if tag == '856':
                subfield_u = datafield.find('.//subfield[@code="u"]')
                if subfield_u is not None:
                    ead_link = subfield_u.text
            elif tag == '852':
                subfield_h = datafield.find('.//subfield[@code="h"]')
                if subfield_h is not None:
                    call_number = subfield_h.text

        if ead_link:
            return 'with_ead'
        elif call_number in call_numbers:
            return 'with_call_number'
        else:
            return 'neither'
    except ET.ParseError as e:
        print(f"Error parsing {marc_file}: {e}")
        return 'error'

def organize_marc_records(marc_dir, ead_dir, output_dirs):
    if not all(os.path.exists(d) for d in [marc_dir, ead_dir] + output_dirs):
        print("One or more directories do not exist.")
        return

    call_numbers = parse_ead_files(ead_dir)

    for filename in os.listdir(marc_dir):
        if filename.endswith('.xml'):
            marc_file = os.path.join(marc_dir, filename)
            category = parse_marc_record(marc_file, call_numbers)
            if category == 'error':
                continue
            dest_dir = output_dirs[category]
            if not os.path.exists(dest_dir):
                os.makedirs(dest_dir)
            shutil.copy(marc_file, dest_dir)

