```python
import argparse
import os
import shutil
import fnmatch

def remove_directory(path, dry_run=False):
    if dry_run:
        print(f"Dry run: Would remove directory: {path}")
    else:
        print(f"Removing: {path}")
        shutil.rmtree(path)

def remove_files(pattern, directory, dry_run=False):
    for root, _, files in os.walk(directory):
        for filename in fnmatch.filter(files, pattern):
            file_path = os.path.join(root, filename)
            if dry_run:
                print(f"Dry run: Would remove file: {file_path}")
            else:
                print(f"Removing: {file_path}")
                os.remove(file_path)

def clean_project_directory(project_dir, dry_run=False):
    # Directories to remove
    directories_to_remove = ['dist', 'build', '.eggs']
    for dir_name in directories_to_remove:
        dir_path = os.path.join(project_dir, dir_name)
        if os.path.exists(dir_path):
            remove_directory(dir_path, dry_run)

    # Recursively remove __pycache__ directories and *.pyc files
    for root, dirs, _ in os.walk(project_dir):
        for dir_name in dirs:
            if dir_name == '__pycache__':
                remove_directory(os.path.join(root, dir_name), dry_run)
        remove_files('*.pyc', root, dry_run)

    # Remove specific file patterns in specific directories
    specific_patterns = {
        'docs/test_to_docs': ['*.png', '*.yml']
    }
    for dir_path, patterns in specific_patterns.items():
        full_dir_path = os.path.join(project_dir, dir_path)
        if os.path.exists(full_dir_path):
            for pattern in patterns:
                remove_files(pattern, full_dir_path, dry_run)

def main():
    parser = argparse.ArgumentParser(description="Clean up a Python project directory.")
    parser.add_argument('project_dir', type=str, help="The project directory to clean.")
    parser.add_argument('--dry-run', action='store_true', help="List files and directories to be removed without deleting them.")

    args = parser.parse_args()

    if not os.path.isdir(args.project_dir):
        print(f"Error: The specified project directory does not exist: {args.project_dir}")
        return

    clean_project_directory(args.project_dir, args.dry_run)

if __name__ == "__main__":
    main()
